insert into public.accords (slug, name, description, hue, sort) values
  ('fresh', 'Fresh', 'Citrus, airy, aquatic and aromatic herbs. The lift you notice first.', '#86A7AE', 0),
  ('clean', 'Clean', 'Musks, aldehydes, soap and laundry. Smells like a fresh shirt.', '#B7C2C4', 1),
  ('green', 'Green', 'Leaves, stems, galbanum, tomato vine, cut grass.', '#7E9473', 2),
  ('floral', 'Floral', 'Rose, jasmine, white flowers, orange blossom.', '#C6928F', 3),
  ('fruity', 'Fruity', 'Pear, berries, stone fruit, tropical fruit.', '#D9A06B', 4),
  ('sweet', 'Sweet', 'Vanilla, caramel, praline, honey. Gourmand territory.', '#B97D45', 5),
  ('creamy', 'Creamy', 'Sandalwood, milk, coconut, lactonic smoothness.', '#DCCBA8', 6),
  ('powdery', 'Powdery', 'Iris, heliotrope, violet. The feel of face powder.', '#A99AA6', 7),
  ('spicy', 'Spicy', 'Pepper, cardamom, cinnamon, clove, saffron.', '#A44B33', 8),
  ('woody', 'Woody', 'Cedar, sandalwood, vetiver, guaiac, oud.', '#8B6B4B', 9),
  ('earthy', 'Earthy', 'Patchouli, oakmoss, vetiver roots, hay.', '#6E6B3F', 10),
  ('warm', 'Warm', 'Amber, resins, labdanum, benzoin, ambroxan warmth.', '#BF8A35', 11),
  ('smoky', 'Smoky', 'Incense, birch tar, tobacco, leather.', '#4B4743', 12);
