insert into public.notes (id, slug, name, kind, family, aliases, smells_like, origin, contributes, synthetic, volatility, character, hue) values
  ('ac6d7f46-9635-57f2-83af-8275fd92a96d', 'bergamot', 'Bergamot', 'material', 'citrus', array['bergamot orange']::text[], 'Bright, slightly bitter citrus with a soft floral edge. If you know Earl Grey tea, you already know bergamot.', 'Cold-pressed from the peel of a bitter citrus grown mostly in Calabria, in southern Italy. Perfume grades usually have bergaptene removed, a compound that can make skin burn more easily in sunlight.', 'Lifts the opening and slides smoothly into florals and woods. It turns up in more classic structures than any other citrus.', 'natural', 'top', '{"fresh":0.9,"fruity":0.2}'::jsonb, '#C9B24A'),
  ('8f8b73df-d4ec-560c-b1cb-734403c8316d', 'lemon', 'Lemon', 'material', 'citrus', array['lemon zest', 'lemon peel']::text[], 'Sharp, zesty and juicy, like scratching the skin of a fresh lemon with your thumbnail.', 'Cold-pressed from lemon peel. The natural oil fades fast, so perfumers often prop it up with citral and other synthetic lemony molecules.', 'A clean, wide-awake opening. On its own it rarely lasts much past the first fifteen minutes.', 'natural', 'top', '{"fresh":0.9,"clean":0.3,"fruity":0.2}'::jsonb, '#D4C35A'),
  ('9938ede9-480e-56a5-bc5a-b6103482c566', 'mandarin', 'Mandarin', 'material', 'citrus', array['mandarin orange', 'tangerine', 'clementine']::text[], 'Sweet, juicy and soft, like peeling a ripe mandarin. Rounder and friendlier than lemon or grapefruit.', 'Cold-pressed from mandarin peel. Green mandarin comes from unripe fruit and smells sharper, while red mandarin is riper and sweeter.', 'Adds a juicy, easygoing brightness to the opening and sits especially well next to florals and ambers.', 'natural', 'top', '{"fresh":0.7,"fruity":0.4,"sweet":0.2}'::jsonb, '#D39A4A'),
  ('c4ac5a74-53b2-525f-af81-76449eb53102', 'sweet-orange', 'Sweet orange', 'material', 'citrus', array['orange', 'orange peel']::text[], 'The fine spray that hits your nose when you peel an orange: sweet, juicy and cheerful.', 'Cold-pressed from orange peel, largely as a by-product of the juice industry, which makes it one of the cheapest natural oils in perfumery.', 'Gives a sunny, sweet start and pairs easily with spice, vanilla and amber. It is gone fairly quickly.', 'natural', 'top', '{"fresh":0.6,"fruity":0.5,"sweet":0.3}'::jsonb, '#D08A3E'),
  ('93682784-6eda-52ae-98f0-808defc7d00a', 'bitter-orange', 'Bitter orange', 'material', 'citrus', array['bigarade', 'seville orange']::text[], 'Drier and sharper than sweet orange, with a bitter peel edge. Think marmalade before anyone adds the sugar.', 'Cold-pressed from the peel of the bitter orange tree. The same tree also gives neroli and orange blossom from its flowers and petitgrain from its leaves and twigs.', 'Brings a grown-up, slightly bitter brightness, common in colognes and older-style compositions.', 'natural', 'top', '{"fresh":0.8,"fruity":0.3,"green":0.2}'::jsonb, '#C27F3A'),
  ('e29d99ab-1753-579a-9960-6a95a7082de7', 'grapefruit', 'Grapefruit', 'material', 'citrus', array['pink grapefruit']::text[], 'Tart, juicy and a little bitter, with the faintly sulfurous pink tang that real grapefruit has. Very awake.', 'Partly cold-pressed from the peel, but the juicy, sulfurous character usually comes from synthetics such as nootkatone and a few extremely potent sulfur molecules.', 'Gives a sparkling, energetic opening and is a staple of fresh and sporty fragrances.', 'both', 'top', '{"fresh":0.9,"fruity":0.4}'::jsonb, '#D08C78'),
  ('a25bb3a8-fd45-531f-945e-6f239cea256a', 'lime', 'Lime', 'material', 'citrus', array['key lime']::text[], 'Sharper and greener than lemon, like a lime wedge squeezed over a cold drink.', 'Cold-pressed or distilled from lime peel. Distilled lime smells candied and soda-like, while pressed lime stays greener and closer to the fruit.', 'Adds a zesty snap to the opening and gets along well with mint, ginger and rum notes.', 'natural', 'top', '{"fresh":0.9,"green":0.3,"fruity":0.2}'::jsonb, '#9DAF4E'),
  ('e75155db-6a90-5f76-bd4e-62fa93f1c82d', 'yuzu', 'Yuzu', 'material', 'citrus', '{}'::text[], 'A Japanese citrus that smells somewhere between grapefruit and mandarin, with a floral, almost herbal tang.', 'Cold-pressed from the peel of the yuzu fruit. The natural oil is scarce and pricey, so many yuzu notes are accords built from other citrus oils and synthetics.', 'Gives a bright, slightly unusual citrus opening that feels more delicate than lemon.', 'both', 'top', '{"fresh":0.9,"fruity":0.3,"floral":0.2}'::jsonb, '#CDBB55'),
  ('55ffe091-f1cc-57af-bcf2-aa861bc53305', 'petitgrain', 'Petitgrain', 'material', 'citrus', array['petitgrain bigarade']::text[], 'Green, woody citrus with a bitter leafy edge, like crushing an orange-tree leaf between your fingers.', 'Steam-distilled from the leaves and twigs of the bitter orange tree. The name means "little grain" and dates from when small unripe fruit went into the still.', 'Adds a crisp green-citrus freshness that holds on a bit longer than peel oils. A backbone of classic colognes.', 'natural', 'top', '{"fresh":0.7,"green":0.5,"woody":0.2}'::jsonb, '#8E9A5A'),
  ('5f6f22b3-c5d6-53ea-8c08-3217697545cd', 'blood-orange', 'Blood orange', 'material', 'citrus', array['red orange', 'sanguine orange']::text[], 'Juicy orange with a darker, berry-like tang. Sweeter and redder than regular orange, if a smell can be red.', 'Blood orange oil exists but is rare, so most blood orange notes are blends of sweet orange, mandarin and fruity synthetics.', 'Brings a juicy, slightly tart fruitiness to the opening, often in playful or fruity-floral compositions.', 'both', 'top', '{"fruity":0.6,"fresh":0.6,"sweet":0.3}'::jsonb, '#B5604A'),
  ('f46fa2e2-16e0-565e-8429-f8812f13927e', 'citron', 'Citron', 'material', 'citrus', array['cedrat', 'cédrat']::text[], 'Like a lemon with less juice and more peel: dry, clean and faintly floral.', 'Cold-pressed from the thick-skinned citron, an ancestor of many modern citrus fruits. Real citron oil is scarce, so the note is often rebuilt from lemon oil and citral.', 'Gives a dry, polished citrus lift for compositions that want freshness without sweetness.', 'both', 'top', '{"fresh":0.9,"clean":0.3}'::jsonb, '#C8C06A'),
  ('f06862f4-50d4-506a-bda2-66dcca7faa64', 'lavender', 'Lavender', 'material', 'aromatic', array['lavandin', 'lavender absolute']::text[], 'Herbal, clean and a little floral, with a cool camphor edge. Think of a lavender sachet in a drawer, or old-fashioned barbershop shaving soap.', 'Steam-distilled from the flowering tops of lavender. Lavandin, a hardier hybrid, gives a sharper, more camphor-like oil and is used widely because it costs less.', 'Brings an aromatic, clean freshness that can lean herbal or soft and sweet. It is the core of the fougère family.', 'natural', 'heart', '{"fresh":0.5,"floral":0.4,"clean":0.4,"green":0.2}'::jsonb, '#8E86A8'),
  ('4c03f87e-eb9c-5bc3-ae07-575c5ba6f5ed', 'rosemary', 'Rosemary', 'material', 'aromatic', '{}'::text[], 'Resinous and herbal with a cooling camphor edge, like rosemary sprigs crushed in your palm.', 'Steam-distilled from the leaves and flowering tops of the rosemary shrub.', 'Adds a brisk herbal snap to the opening. Common in colognes and fougères.', 'natural', 'top', '{"fresh":0.6,"green":0.6}'::jsonb, '#6F7F5C'),
  ('a4684867-0bd0-575d-8567-0edbe200c81d', 'clary-sage', 'Clary sage', 'material', 'aromatic', array['sage', 'salvia sclarea']::text[], 'Herbal and musky with hints of tea and hay, a little like warm skin. Softer and rounder than kitchen sage.', 'Steam-distilled from the flowering tops of clary sage. Sclareol, one of its components, is the usual starting point for making ambroxan.', 'Gives an aromatic, faintly ambery warmth that links a fresh opening to a woody base.', 'natural', 'heart', '{"green":0.4,"fresh":0.3,"warm":0.3,"earthy":0.2}'::jsonb, '#7D7F68'),
  ('0cbe775a-fc05-5b69-bea0-b81d0dcaf75d', 'basil', 'Basil', 'material', 'aromatic', array['sweet basil']::text[], 'Sweet, green and peppery with a hint of anise, like tearing basil leaves over a tomato salad.', 'Steam-distilled from the leaves and flowering tops of sweet basil.', 'Adds a lively green, slightly spicy edge, often next to citrus or mint.', 'natural', 'top', '{"green":0.7,"fresh":0.5,"spicy":0.2}'::jsonb, '#5E7A4E'),
  ('6ff7f2af-4fc1-54e3-8b30-92f50d97efec', 'mint', 'Mint', 'material', 'aromatic', array['peppermint', 'spearmint']::text[], 'Cool and sharp, like toothpaste or chewing gum. Spearmint is sweeter and softer; peppermint is icier.', 'Steam-distilled from mint leaves. Menthol and other cooling molecules are often added to push the chill further.', 'Gives an instant cooling effect up top. It fades fast, but it sets a crisp first impression.', 'natural', 'top', '{"fresh":0.9,"green":0.4}'::jsonb, '#7FA38A'),
  ('f0768d1a-ae20-5fc5-950d-7b0921f7a981', 'thyme', 'Thyme', 'material', 'aromatic', '{}'::text[], 'Warm, dry and herbal with a slightly medicinal bite, like a herb garden baking in the sun.', 'Steam-distilled from thyme leaves and flowers. Thymol, its main molecule, supplies the antiseptic edge.', 'Adds a warm, dry aromatic quality, often in herbal or Mediterranean-style compositions.', 'natural', 'heart', '{"green":0.5,"spicy":0.3,"warm":0.3}'::jsonb, '#7A7A55'),
  ('976b6674-d6b2-507c-b967-778199a934a7', 'artemisia', 'Artemisia', 'material', 'aromatic', array['wormwood', 'mugwort', 'armoise']::text[], 'Bitter, green and a bit medicinal, with the herbal sharpness of a glass of absinthe.', 'Steam-distilled from the leaves and flowering tops of various artemisia plants, including wormwood and mugwort.', 'Adds a bitter aromatic edge that stops sweet or floral compositions from going soft.', 'natural', 'top', '{"green":0.7,"fresh":0.3,"earthy":0.2}'::jsonb, '#7E8B6A'),
  ('08f7aaea-afaf-59f7-aab3-19599c5fd858', 'juniper-berry', 'Juniper berry', 'material', 'aromatic', array['juniper']::text[], 'Piney, resinous and slightly peppery. If you have smelled gin, you have smelled juniper.', 'Steam-distilled from the crushed, dried berries of the juniper shrub.', 'Brings a crisp, coniferous freshness to the opening of aromatic and woody fragrances.', 'natural', 'top', '{"fresh":0.6,"woody":0.4,"green":0.3,"spicy":0.2}'::jsonb, '#5D6C7A'),
  ('b52c5d08-efe5-56f5-89ad-68888d7a0785', 'geranium', 'Geranium', 'material', 'aromatic', array['rose geranium', 'pelargonium', 'geranium bourbon']::text[], 'Rosy and green with a minty, slightly metallic edge, like rubbing the leaves of a potted geranium.', 'Steam-distilled from the leaves and stems of pelargonium plants, not the flowers. It shares several molecules with rose, which is why it smells rosy.', 'Adds a fresh, rosy brightness that works in fougères and florals alike. Often used to support or stretch a rose note.', 'natural', 'heart', '{"floral":0.5,"green":0.5,"fresh":0.3}'::jsonb, '#A8737A'),
  ('1b89f07b-9919-5064-8e68-b1ee82765feb', 'tarragon', 'Tarragon', 'material', 'aromatic', array['estragon']::text[], 'Green and herbal with a sweet anise twist, as if licorice grew in a herb garden.', 'Steam-distilled from tarragon leaves. The anise character comes from a molecule called estragole.', 'Adds a fresh, faintly sweet herbal accent to openings, especially in aromatic and fougère styles.', 'natural', 'top', '{"green":0.6,"fresh":0.4,"sweet":0.2}'::jsonb, '#7C8C58'),
  ('9e8a71a8-ccc8-54c1-ab8d-e506e9f59e6d', 'violet-leaf', 'Violet leaf', 'material', 'green', array['violet leaves']::text[], 'Sharp, green and watery, like fresh cucumber skin mixed with crushed leaves. Nothing like the sweet violet flower note.', 'Solvent-extracted from violet leaves as an absolute. Its cucumber-green molecule is also made synthetically and used to stretch the natural.', 'Gives an intense, cool green freshness. A drop goes a long way.', 'both', 'top', '{"green":0.9,"fresh":0.5}'::jsonb, '#5F7A55'),
  ('4837a78d-85fa-5335-bf84-20d9f1f1f183', 'galbanum', 'Galbanum', 'material', 'green', '{}'::text[], 'Very sharp, bitter green, like snapping a thick, sappy plant stem. Some find it piercing at first.', 'A gum resin tapped from a plant in the fennel family that grows in Iran and Central Asia, used as an essential oil, resinoid or absolute.', 'Adds a dramatic green bite to the opening. A classic in green chypres and green florals.', 'natural', 'top', '{"green":1,"fresh":0.4,"earthy":0.2}'::jsonb, '#6B7A4A'),
  ('f9516d12-fdc3-59b6-884d-33db9f8d7c00', 'fig-leaf', 'Fig leaf', 'material', 'green', array['fig tree']::text[], 'Green, milky and faintly coconut-like, like standing under a fig tree on a hot afternoon.', 'Fig leaf absolute exists but is restricted and costly, so most fig leaf notes lean on synthetics that recreate the green, milky effect.', 'Brings a lush, green-creamy freshness, popular in summery and Mediterranean-style scents.', 'both', 'heart', '{"green":0.7,"creamy":0.4,"fresh":0.3}'::jsonb, '#6F8A5E'),
  ('ff1423b2-8721-58e5-94b7-2a028f25f1be', 'tomato-leaf', 'Tomato leaf', 'material', 'green', array['tomato vine']::text[], 'Pungent, bitter green, exactly like brushing past tomato plants in a warm greenhouse.', 'Natural tomato leaf extracts are rare, so the note is usually built from green synthetic molecules.', 'Adds a vivid, realistic garden greenness that feels unusual in a composition.', 'both', 'top', '{"green":0.9,"fresh":0.3,"earthy":0.2}'::jsonb, '#5A7448'),
  ('039f6b35-40f8-5466-b1f3-86bd5ab07791', 'blackcurrant-bud', 'Blackcurrant bud', 'material', 'green', array['cassis bud', 'bourgeon de cassis']::text[], 'Sharp, green and fruity with a catty, faintly sulfurous edge. It sounds odd, and it works anyway.', 'Solvent-extracted as an absolute from the dormant buds of the blackcurrant bush. Potent sulfur compounds give it the tang.', 'Gives a tart green-fruity sharpness to openings and fruity florals, more grown-up than the berry itself.', 'natural', 'top', '{"green":0.6,"fruity":0.5}'::jsonb, '#5E5A62'),
  ('b8f6283b-a617-537e-8afc-5ee6ac79413d', 'rhubarb', 'Rhubarb', 'accord', 'green', '{}'::text[], 'Tart and green with a rosy, fruity crunch, like biting a raw stick of rhubarb.', 'Rhubarb is not extracted for perfume. The note comes from synthetic molecules that reproduce its sour, green and rosy sides.', 'Adds a crisp, sour-green sparkle to openings, often alongside citrus and rose.', 'synthetic', 'top', '{"green":0.6,"fresh":0.5,"fruity":0.4}'::jsonb, '#B07A78'),
  ('1abb82f2-d173-5720-bec7-0b12faf46e7c', 'cut-grass', 'Cut grass', 'accord', 'green', array['freshly cut grass', 'grass', 'green grass']::text[], 'A lawn that was mowed five minutes ago: bright, green and a little sharp.', 'An accord built mostly on cis-3-hexenol, the molecule plants release when their leaves are cut, with other green synthetics around it.', 'Adds a vivid, outdoorsy greenness to the opening.', 'synthetic', 'top', '{"green":0.9,"fresh":0.6}'::jsonb, '#6E8F4E'),
  ('55fb803f-73bf-5591-86e6-1be08c40cd61', 'bamboo', 'Bamboo', 'accord', 'green', '{}'::text[], 'Fresh, watery and green, like a cool leafy stalk. Airy rather than sharp.', 'An accord, since bamboo is not extracted for perfume. Usually a mix of green, watery and light woody synthetics.', 'Adds a clean, airy green quality, common in fresh and spa-like compositions.', 'synthetic', 'heart', '{"green":0.6,"fresh":0.6,"clean":0.3}'::jsonb, '#8FA27A'),
  ('856acaad-5c50-5aa4-9afd-f624e4f3216c', 'cucumber', 'Cucumber', 'accord', 'green', '{}'::text[], 'Cool, watery and green, like a cucumber slice straight from the fridge.', 'An accord built mainly on nonadienal and related molecules, the same compounds found in cucumber skin and violet leaf.', 'Gives a crisp, watery coolness to fresh fragrances.', 'synthetic', 'top', '{"fresh":0.8,"green":0.6}'::jsonb, '#9AB08A'),
  ('636a9758-edbd-576f-9918-78d15147d494', 'marine-notes', 'Marine notes', 'accord', 'marine', array['sea notes', 'ocean notes', 'aquatic notes', 'water notes']::text[], 'A clean, breezy idea of the sea: watery, airy and slightly salty. Less real beach, more the ocean from a shampoo ad.', 'An accord of synthetic molecules such as calone and other watery, ozonic materials. Nobody can distill the sea.', 'Gives a cool, watery freshness. The defining note of the aquatic family.', 'synthetic', 'top', '{"fresh":0.9,"clean":0.5}'::jsonb, '#7A9AA8'),
  ('75869265-2e67-5430-8e45-13dcbe85bc45', 'sea-salt', 'Sea salt', 'accord', 'marine', array['salt', 'salty', 'sea spray']::text[], 'Skin after a swim in the sea: mineral, warm and faintly savory.', 'An accord, since salt itself has no smell. Perfumers combine mineral, ambery and marine molecules (ambroxan is a frequent helper) to suggest it.', 'Adds a salty, skin-like texture that makes fresh or woody fragrances feel more lived-in.', 'synthetic', 'heart', '{"fresh":0.5,"warm":0.3,"clean":0.3}'::jsonb, '#A9B3B0'),
  ('516caf02-fd25-5420-93e8-ba2d3d7f8bbf', 'calone', 'Calone', 'material', 'marine', array['watermelon ketone']::text[], 'Watery and breezy with an odd melon sweetness, like cut watermelon at the beach.', 'A synthetic molecule discovered in the 1960s that became the signature of the 1990s aquatic wave.', 'A trace gives sea-spray freshness; a bit more and everything smells of melon. The backbone of many aquatic fragrances.', 'synthetic', 'top', '{"fresh":0.9,"fruity":0.3}'::jsonb, '#8FB0B2'),
  ('811ab213-d386-53f7-aa41-dbf3e574524e', 'seaweed', 'Seaweed', 'material', 'marine', array['algae', 'kelp', 'seaweed absolute']::text[], 'Salty, iodine-rich and a little green, like seaweed drying on rocks at low tide.', 'Absolutes and extracts are made from brown seaweeds, though many seaweed notes are partly or fully synthetic.', 'Adds a realistic, briny shoreline character, rougher than clean marine notes.', 'both', 'heart', '{"fresh":0.4,"green":0.4,"earthy":0.4}'::jsonb, '#4E6A58'),
  ('2a32ac2e-4330-5d13-b60a-828945f201cf', 'petrichor', 'Petrichor', 'accord', 'marine', array['rain', 'after rain', 'wet earth']::text[], 'Rain hitting dry ground: earthy, mineral and fresh all at once.', 'An accord. Part of the real smell comes from geosmin, a molecule made by soil bacteria, which perfumers use in tiny amounts with mineral and green notes.', 'Adds a cool, damp, earthy freshness and gives a fragrance a sense of weather.', 'synthetic', 'heart', '{"fresh":0.6,"earthy":0.5,"green":0.2}'::jsonb, '#7D8580'),
  ('8dd0a27d-c658-5a46-9406-55eca1da1417', 'rose', 'Rose', 'material', 'floral', array['rose absolute', 'rose otto', 'damask rose', 'rose de mai', 'centifolia']::text[], 'Rich and petal-soft, slightly fruity, sometimes with a honeyed or spicy edge. Fresh roses in a vase, only deeper.', 'Steam-distilled into rose oil (otto) or solvent-extracted into rose absolute, mainly from Damask roses in Bulgaria and Turkey and centifolia roses in Morocco and France. Synthetic rose molecules such as phenylethyl alcohol and citronellol are used heavily too.', 'Gives body and warmth to the floral heart. Depending on its neighbors it can read fresh, jammy, dark or powdery.', 'both', 'heart', '{"floral":0.9,"fruity":0.2,"sweet":0.2}'::jsonb, '#A85A64'),
  ('352c148b-63c0-591d-8cf1-2c96fa5e6f89', 'jasmine', 'Jasmine', 'material', 'floral', array['jasmin', 'jasmine sambac', 'sambac', 'jasmine grandiflorum']::text[], 'Lush, sweet white floral with an indolic, faintly animal undertone that makes it feel warm and skin-like.', 'Solvent-extracted as an absolute from jasmine flowers, mostly grandiflorum and sambac from India and Egypt. Synthetics like hedione and benzyl acetate are often used to build or stretch it.', 'Adds richness and radiance to a floral heart. Hedione, a jasmine-derived synthetic, gives airy lift to all sorts of fragrances.', 'both', 'heart', '{"floral":0.9,"sweet":0.3,"warm":0.2}'::jsonb, '#E2D6B0'),
  ('d51fec2b-e0f1-58c0-b01f-b7f10aa23241', 'orange-blossom', 'Orange blossom', 'material', 'floral', array['orange flower', 'fleur d''oranger']::text[], 'Sweet, honeyed and slightly soapy white floral, warmer and more indolic than neroli. A citrus grove in bloom at dusk.', 'Solvent-extracted as an absolute from the flowers of the bitter orange tree. Steam-distill the same flowers and you get neroli instead.', 'Adds a radiant, sweet floral warmth that can come across as clean or sensual. Common in florals and ambers.', 'natural', 'heart', '{"floral":0.8,"sweet":0.4,"clean":0.2}'::jsonb, '#E8D5A8'),
  ('97ffd5b8-f2e5-5aec-851d-14516c7d2a02', 'neroli', 'Neroli', 'material', 'floral', '{}'::text[], 'Fresh, green-floral with a bitter citrus edge. Lighter and cleaner than orange blossom.', 'Steam-distilled from the flowers of the bitter orange tree. The water left over from distillation is sold as orange flower water.', 'Bridges citrus top notes into the floral heart with a clean, sunny brightness. A pillar of the classic cologne.', 'natural', 'top', '{"floral":0.6,"fresh":0.6,"clean":0.3}'::jsonb, '#E0CF9A'),
  ('e20bb0cc-d767-5459-ba6a-8a11bb75b23c', 'tuberose', 'Tuberose', 'material', 'floral', array['polianthes']::text[], 'Creamy, buttery and intensely sweet white floral, with a rubbery, almost camphor-like edge up close. Loud, and it knows it.', 'Solvent-extracted as an absolute from tuberose flowers, mostly grown in India. The absolute is expensive, so synthetics often support it.', 'Gives a bold, creamy floral heart that tends to take over whatever it is in.', 'both', 'heart', '{"floral":0.9,"creamy":0.5,"sweet":0.4}'::jsonb, '#EADCC0'),
  ('a47f136d-d22b-5d8b-858d-be75c1481eab', 'iris', 'Iris', 'material', 'floral', array['orris', 'orris root', 'orris butter']::text[], 'Cool, powdery and soft, somewhere between lipstick, raw carrot and a clean cotton shirt. Barely floral, despite the name.', 'Comes from the root, not the flower. Iris rhizomes are dried and aged for about three years, then distilled into orris butter, one of the most expensive materials in perfumery. Synthetic irones and ionones help support it.', 'Brings a cool, refined powderiness with an earthy depth. It makes compositions feel restrained.', 'both', 'heart', '{"powdery":0.9,"floral":0.4,"earthy":0.2}'::jsonb, '#9C94A8'),
  ('a822423a-d30a-5812-b850-5ce09fec191f', 'violet', 'Violet', 'accord', 'floral', array['violets', 'parma violet', 'ionones']::text[], 'Sweet, powdery and candy-like, like old-fashioned violet sweets or a makeup compact.', 'The flower is almost never extracted. Violet notes are built from ionones, synthetic molecules first made in the 1890s, often with a touch of violet leaf for green.', 'Adds a soft, powdery sweetness that can feel nostalgic or cosmetic. Pairs well with iris, rose and woods.', 'synthetic', 'heart', '{"powdery":0.7,"floral":0.6,"sweet":0.4}'::jsonb, '#7D6A92'),
  ('4352f2d0-5e4b-54ba-b8e5-1d90d2a7e9a8', 'ylang-ylang', 'Ylang-ylang', 'material', 'floral', array['ylang', 'ylang ylang']::text[], 'Rich, creamy tropical floral with a hint of banana and a slightly medicinal edge.', 'Steam-distilled from the flowers of a tree native to Southeast Asia, now grown largely in the Comoros and Madagascar. The distillation is split into fractions, from the light "extra" grade to heavier ones.', 'Gives a sweet, sunny, creamy floral body. Common in florals and ambers.', 'natural', 'heart', '{"floral":0.8,"creamy":0.4,"sweet":0.4,"fruity":0.2}'::jsonb, '#D8C27A'),
  ('cbd8b605-3514-5764-b2ca-54653d776915', 'magnolia', 'Magnolia', 'material', 'floral', array['champaca', 'michelia']::text[], 'Lemony, creamy and fresh floral. Lighter and brighter than gardenia or tuberose.', 'Oils are produced from the flowers and leaves of michelia trees, close relatives of magnolia, but many magnolia notes are partly or fully synthetic.', 'Adds a fresh, slightly citrusy floral brightness to the heart.', 'both', 'heart', '{"floral":0.8,"fresh":0.4,"creamy":0.2}'::jsonb, '#E3D3C2'),
  ('8f81ad03-f063-5183-81f7-e38a9b28c342', 'peony', 'Peony', 'accord', 'floral', array['pivoine']::text[], 'Fresh, rosy and lightly fruity. Airy rather than heady, like a bouquet in a cool room.', 'An accord, since peonies yield no usable extract. Built from rosy, fruity and fresh synthetic molecules.', 'Adds a soft, bright pink floral tone, common in fresh and fruity florals.', 'synthetic', 'heart', '{"floral":0.8,"fresh":0.4,"fruity":0.2}'::jsonb, '#C8909A'),
  ('ae5b29a8-e640-53fa-8aa0-7e607a062ffd', 'lily-of-the-valley', 'Lily of the valley', 'accord', 'floral', array['muguet']::text[], 'Clean, green and dewy white floral, like fresh laundry left out in a spring garden.', 'The flower gives no usable extract, so this is always an accord, mostly synthetic with some natural florals. Several of its key molecules have been restricted in recent years, so perfumers keep rebuilding it.', 'Adds an airy, clean brightness to florals. It is often the reason a fragrance smells "clean" in a way you cannot pin down.', 'both', 'heart', '{"floral":0.7,"clean":0.6,"green":0.3,"fresh":0.3}'::jsonb, '#D7DCC4'),
  ('ead64a16-1d34-5d52-87ab-6e085f1366ab', 'gardenia', 'Gardenia', 'accord', 'floral', '{}'::text[], 'Creamy, lush white floral with a green, slightly mushroomy edge. Richer and earthier than jasmine.', 'Gardenia extract is extremely rare, so the note is an accord of jasmine, tuberose and other naturals with synthetic molecules.', 'Gives a velvety, creamy floral heart.', 'both', 'heart', '{"floral":0.9,"creamy":0.5,"green":0.2}'::jsonb, '#E8E0C8'),
  ('700d5f9e-a562-594f-ac6f-75129254a705', 'osmanthus', 'Osmanthus', 'material', 'floral', array['sweet olive', 'tea olive']::text[], 'Apricot, suede and tea, all from one tiny flower. Fruity, soft and faintly smoky.', 'Solvent-extracted as an absolute from the small flowers of a shrub native to China, where it also flavors tea and sweets.', 'Adds a fruity, leathery warmth that makes florals and tea notes feel rich and unusual.', 'natural', 'heart', '{"floral":0.6,"fruity":0.6,"warm":0.2}'::jsonb, '#D49A5A'),
  ('ac4b6203-aa06-5d06-b2bd-79309e11a1a9', 'mimosa', 'Mimosa', 'material', 'floral', array['acacia', 'silver wattle']::text[], 'Soft, honeyed and powdery with a faint green, almond-like edge, about as gentle as the fuzzy yellow flowers look.', 'Solvent-extracted as an absolute from the flowers and twigs of the mimosa tree, a type of acacia grown widely in the south of France.', 'Adds a cozy, powdery floral warmth, often alongside iris, violet and heliotrope.', 'natural', 'heart', '{"powdery":0.6,"floral":0.6,"sweet":0.3}'::jsonb, '#D4BF5E'),
  ('a20bb8f6-1b89-530c-b1fd-707c0db79d29', 'heliotrope', 'Heliotrope', 'accord', 'floral', array['heliotropin', 'piperonal']::text[], 'Powdery, almondy and vanilla-like, a bit like marzipan dusted with baby powder.', 'An accord, since the flower gives no usable extract. Built mostly on heliotropin (piperonal), plus vanillin and coumarin.', 'Adds a soft, powdery sweetness that bridges florals and gourmand bases.', 'synthetic', 'heart', '{"powdery":0.8,"sweet":0.5,"floral":0.3}'::jsonb, '#A99AB8'),
  ('173fdde5-a573-5eb9-9a04-437b096989da', 'carnation', 'Carnation', 'accord', 'floral', array['clove pink', 'dianthus', 'oeillet']::text[], 'Spicy floral, like a rose that swallowed a clove. Peppery, warm and a little old-fashioned.', 'Carnation absolute exists but is very rare today, so the note is usually an accord of eugenol (the main molecule in clove) with rose and other florals.', 'Adds a warm, spicy twist to a floral heart.', 'both', 'heart', '{"floral":0.6,"spicy":0.6}'::jsonb, '#B8676A'),
  ('6fe37274-c0d6-5cfa-8897-5cb4dd02a44f', 'frangipani', 'Frangipani', 'accord', 'floral', array['plumeria']::text[], 'Creamy, tropical fruity-floral with hints of peach, coconut and sun lotion.', 'An accord of other florals and synthetic molecules, since frangipani extracts are scarce.', 'Gives a sunny, creamy floral body, common in summery and beachy compositions.', 'both', 'heart', '{"floral":0.8,"creamy":0.4,"fruity":0.3,"sweet":0.3}'::jsonb, '#E6C9A8'),
  ('47a55ca1-6eec-546d-a250-77dfbd42c3dd', 'honeysuckle', 'Honeysuckle', 'accord', 'floral', array['woodbine']::text[], 'Sweet, nectar-like and green, like the flowers you pulled apart as a kid to taste the drop inside.', 'An accord, since honeysuckle has no commercial extract. Built from sweet floral, fruity and green synthetics.', 'Adds a sweet, sunny floral note with a fresh green edge.', 'synthetic', 'heart', '{"floral":0.7,"sweet":0.5,"green":0.3}'::jsonb, '#E0CB8E'),
  ('8835bbe2-147f-5201-9353-a056694f56bb', 'pear', 'Pear', 'accord', 'fruity', '{}'::text[], 'Crisp, juicy and lightly sweet, like biting into a ripe pear.', 'An accord built on fruity esters and other synthetics. Pears are not extracted for perfume.', 'Adds a juicy, fresh sweetness to the opening without much weight.', 'synthetic', 'top', '{"fruity":0.8,"fresh":0.4,"sweet":0.3}'::jsonb, '#C3C27A'),
  ('463e14a0-edc4-5e60-807b-8833fc683859', 'green-apple', 'Green apple', 'accord', 'fruity', array['apple']::text[], 'Tart, crunchy and juicy, like a sour green apple or apple-flavored candy.', 'An accord of fruity esters and green synthetic molecules.', 'Adds a bright, crisp fruitiness to fresh and casual fragrances.', 'synthetic', 'top', '{"fruity":0.7,"fresh":0.6,"green":0.3}'::jsonb, '#A8B860'),
  ('c139f941-42d7-5773-ab26-fc15e136a4e5', 'blackcurrant', 'Blackcurrant', 'accord', 'fruity', array['cassis', 'black currant']::text[], 'Dark, tart and jammy berry, like blackcurrant cordial, with a green edge.', 'Blackcurrant bud absolute supplies the green tang and synthetic fruity molecules supply the juicy berry. Most blackcurrant notes in perfume combine the two.', 'Adds a tart, dark fruitiness that keeps sweet florals from getting too sugary.', 'both', 'top', '{"fruity":0.8,"sweet":0.3,"green":0.2}'::jsonb, '#5A3A52'),
  ('19cf6a66-1838-5a76-8762-3a0498d26bae', 'fig', 'Fig', 'accord', 'fruity', array['fig fruit']::text[], 'Milky, sweet and soft, like the inside of a ripe fig, with a little green from the skin.', 'An accord combining milky, lactonic and green synthetics with woods and sometimes coconut notes.', 'Gives a creamy, fruity-green softness, often paired with fig leaf.', 'synthetic', 'heart', '{"fruity":0.6,"creamy":0.5,"green":0.3,"sweet":0.3}'::jsonb, '#7E5A6A'),
  ('94dd9631-398b-5b7c-ae15-07af7647a4c0', 'peach', 'Peach', 'accord', 'fruity', array['apricot']::text[], 'Soft, juicy and velvety, like the fuzzy skin of a ripe peach.', 'An accord built mainly on lactones such as gamma-undecalactone, which give the creamy, skin-like fruit.', 'Adds a soft, round fruitiness that melts into florals and musks.', 'synthetic', 'heart', '{"fruity":0.8,"sweet":0.4,"creamy":0.3}'::jsonb, '#DDA77F'),
  ('ab65aaa1-85f3-58f9-9c6b-638cdff51b39', 'plum', 'Plum', 'accord', 'fruity', array['prune']::text[], 'Dark, jammy and slightly boozy, like stewed plums or prunes.', 'An accord of fruity lactones and esters, sometimes with a little natural extract for depth.', 'Adds a rich, dark fruitiness, common in ambers, roses and evening fragrances.', 'synthetic', 'heart', '{"fruity":0.7,"sweet":0.5,"warm":0.3}'::jsonb, '#6E3E52'),
  ('efb06fcc-a7e6-5c39-9137-f55ce0c68367', 'cherry', 'Cherry', 'accord', 'fruity', array['black cherry', 'sour cherry']::text[], 'Sweet and almondy, closer to cherry candy or cherry liqueur than a fresh cherry from the tree.', 'An accord built around benzaldehyde, the molecule behind both almond and cherry, with fruity synthetics.', 'Adds a sweet, slightly boozy fruitiness, often in gourmand or playful compositions.', 'synthetic', 'heart', '{"fruity":0.7,"sweet":0.7}'::jsonb, '#8E3A44'),
  ('e3b8ff4e-6701-53b4-981b-a724c56dbc05', 'raspberry', 'Raspberry', 'accord', 'fruity', '{}'::text[], 'Sweet, tart and jammy, like raspberry jam or a raspberry sweet.', 'An accord built around raspberry ketone and ionones.', 'Adds a bright, sweet-tart fruitiness, often in fruity florals.', 'synthetic', 'top', '{"fruity":0.8,"sweet":0.5}'::jsonb, '#A84A5C'),
  ('654c41cb-eafe-5342-9ac8-b79f59d1e5b2', 'pineapple', 'Pineapple', 'accord', 'fruity', '{}'::text[], 'Juicy, sweet-tart and tropical, like fresh pineapple chunks.', 'An accord of fruity esters, with allyl caproate often doing most of the work.', 'Adds a loud, juicy brightness to the opening that can read fresh or sweet.', 'synthetic', 'top', '{"fruity":0.8,"fresh":0.4,"sweet":0.4}'::jsonb, '#CDB04E'),
  ('a6ab9799-d970-58e3-9159-9b17a9c3b293', 'coconut', 'Coconut', 'accord', 'fruity', '{}'::text[], 'Creamy, milky and sweet, like coconut milk or a bottle of sun lotion.', 'An accord built on lactones, especially gamma-nonalactone, the same family behind peach and milk notes.', 'Adds a creamy, beachy sweetness, common in summery and gourmand fragrances.', 'synthetic', 'heart', '{"creamy":0.8,"sweet":0.5,"fruity":0.2}'::jsonb, '#E7DCC7'),
  ('54ecfe75-bc5b-51be-9dd2-1d282ac429bc', 'lychee', 'Lychee', 'accord', 'fruity', array['litchi']::text[], 'Juicy, rosy and sweet, like a lychee peeled fresh from the shell.', 'An accord of fruity and rosy synthetic molecules.', 'Adds a juicy, slightly floral fruitiness that pairs naturally with rose.', 'synthetic', 'top', '{"fruity":0.8,"floral":0.3,"sweet":0.3}'::jsonb, '#D9A8A6'),
  ('b099af62-7fd5-5fa8-b889-475fda5b795a', 'pink-pepper', 'Pink pepper', 'material', 'spice', array['pink peppercorn', 'baies roses', 'schinus']::text[], 'Bright, fizzy and slightly fruity spice, more sparkle than heat. Pepper with a citrus twist.', 'Distilled or CO2-extracted from the dried berries of the Peruvian pepper tree, which is not related to black pepper.', 'Adds a zesty, rosy sparkle to openings. It has become one of the most common top notes of the last twenty years.', 'natural', 'top', '{"spicy":0.6,"fresh":0.5,"fruity":0.2}'::jsonb, '#B8737A'),
  ('882bb2c3-32ce-5de3-b44a-2ba052852600', 'black-pepper', 'Black pepper', 'material', 'spice', array['pepper']::text[], 'Dry, woody and sharp, like freshly cracked peppercorns, minus the sneeze.', 'Steam-distilled or CO2-extracted from black peppercorns.', 'Adds a dry, spicy kick to the opening, common in woody and fresh-spicy fragrances.', 'natural', 'top', '{"spicy":0.8,"woody":0.3,"fresh":0.2}'::jsonb, '#4E4A45'),
  ('efb87dae-ca3d-57a5-9a8d-f7cf023f5321', 'cardamom', 'Cardamom', 'material', 'spice', array['cardamon']::text[], 'Cool, aromatic and lemony spice, like chai or a warm cardamom bun.', 'Steam-distilled or CO2-extracted from the seeds of the cardamom plant.', 'Adds an airy spice that sits between fresh and warm. Especially good with woods, iris and coffee.', 'natural', 'top', '{"spicy":0.6,"fresh":0.5,"warm":0.2}'::jsonb, '#8A9070'),
  ('82a0d6f1-14ce-5e9d-a0e1-8578afa6bbc8', 'cinnamon', 'Cinnamon', 'material', 'spice', array['cinnamon bark', 'cassia']::text[], 'Warm, sweet and spicy, like cinnamon sticks or a fresh cinnamon roll.', 'Distilled from the bark or leaves of the cinnamon tree. Bark oil and its main molecule are tightly limited as skin sensitizers, so perfumers often build cinnamon accords instead.', 'Adds a warm, sweet spice that makes ambers and gourmands feel cozier.', 'both', 'heart', '{"spicy":0.8,"warm":0.6,"sweet":0.3}'::jsonb, '#9A5A36'),
  ('270f4c3a-a9d2-5f72-b9e8-6cad15d0c505', 'clove', 'Clove', 'material', 'spice', array['clove bud']::text[], 'Hot, sweet and medicinal spice, somewhere between mulled wine and a dentist’s office.', 'Distilled from clove buds, leaves or stems. Eugenol, its main molecule, is also the heart of the carnation note.', 'Adds a strong, warm spiciness. A little reads cozy; a lot reads dental.', 'natural', 'heart', '{"spicy":0.9,"warm":0.5}'::jsonb, '#6A4A3A'),
  ('513b1b6a-db92-5059-b2b2-a20846284f5c', 'nutmeg', 'Nutmeg', 'material', 'spice', array['mace']::text[], 'Warm, woody and lightly sweet, like nutmeg grated over eggnog.', 'Steam-distilled from the seed of the nutmeg tree. Mace comes from the lacy coating around the same seed.', 'Adds a soft, woody spice that warms up aromatic and woody fragrances.', 'natural', 'heart', '{"spicy":0.7,"warm":0.4,"woody":0.3}'::jsonb, '#8A6A4E'),
  ('cf9d82e1-b21b-5de5-a18e-2fc648eb3c6c', 'saffron', 'Saffron', 'material', 'spice', array['safran', 'safraleine']::text[], 'Leathery, honeyed and a little metallic, like a warm spice rubbed into suede.', 'Real saffron extract is precious and rarely used. Saffron notes usually rely on synthetic molecules such as safraleine.', 'Adds a warm, leathery spice that pairs especially well with rose, oud and amber.', 'synthetic', 'heart', '{"spicy":0.6,"warm":0.5,"sweet":0.2}'::jsonb, '#B5743E'),
  ('b751b0b4-2945-5202-b738-c6966797947e', 'ginger', 'Ginger', 'material', 'spice', array['ginger root']::text[], 'Fresh, zingy and lemony with a warm bite, like freshly grated ginger root.', 'Steam-distilled or CO2-extracted from the dried root of the ginger plant.', 'Adds a fresh, spicy fizz to the opening that works in both fresh and warm fragrances.', 'natural', 'top', '{"spicy":0.6,"fresh":0.6,"warm":0.2}'::jsonb, '#C1A066'),
  ('4e560906-9a8d-5fc7-aca0-88fb5409daba', 'cumin', 'Cumin', 'material', 'spice', '{}'::text[], 'Warm, earthy and sweaty, like cumin seeds in a hot pan. Overdosed, it reads as body odor, which is sometimes the point.', 'Steam-distilled from cumin seeds.', 'Adds a warm, animalic, skin-like spice. Divisive in larger doses.', 'natural', 'heart', '{"spicy":0.8,"earthy":0.4,"warm":0.4}'::jsonb, '#8A6A3A'),
  ('9a467378-4012-5f85-ad18-3071b5fc60a4', 'vanilla', 'Vanilla', 'material', 'gourmand', array['vanilla bean', 'vanilla absolute', 'vanillin', 'bourbon vanilla']::text[], 'Sweet, creamy and warm, like vanilla ice cream. Real vanilla pods are also a bit smoky and boozy.', 'Natural vanilla comes from cured vanilla pods, extracted as an absolute or CO2 extract. Most vanilla notes lean heavily on synthetic vanillin and ethyl vanillin, which are cheaper and more consistent.', 'Adds sweetness, comfort and staying power. One of the most loved base notes in modern perfumery.', 'both', 'base', '{"sweet":0.9,"warm":0.5,"creamy":0.3}'::jsonb, '#D2B48A'),
  ('b2f2ed99-0b12-5bb7-9c4a-02fc3fb48bbf', 'tonka-bean', 'Tonka bean', 'material', 'gourmand', array['tonka', 'tonka absolute']::text[], 'Sweet, warm and almondy, like vanilla mixed with fresh hay and a hint of pipe tobacco.', 'Solvent-extracted from the seeds of a South American tree. Its main molecule, coumarin, was one of the first synthetics used in perfume and is still used widely on its own.', 'Adds a warm, sweet depth that sits between vanilla and hay. Essential to fougères and many gourmands.', 'both', 'base', '{"sweet":0.7,"warm":0.6,"powdery":0.2}'::jsonb, '#9A7A58'),
  ('667e2fcf-68fd-5859-94ae-cbeb8cf53238', 'caramel', 'Caramel', 'accord', 'gourmand', array['toffee', 'burnt sugar']::text[], 'Sweet, buttery and slightly burnt, like caramel sauce or toffee.', 'An accord built around synthetics such as ethyl maltol, often with vanilla and buttery notes.', 'Adds a sticky, dessert-like sweetness that lasts a long time.', 'synthetic', 'base', '{"sweet":0.9,"warm":0.4}'::jsonb, '#A86F3A'),
  ('03400485-4e55-51c5-a5f8-7b979ac2449c', 'praline', 'Praline', 'accord', 'gourmand', array['hazelnut praline', 'nougat']::text[], 'Toasted nuts in caramel, like the sugared nuts sold at a winter fair.', 'An accord combining caramel, vanilla and nutty synthetic molecules.', 'Adds a rich, nutty sweetness to gourmand and amber bases.', 'synthetic', 'base', '{"sweet":0.9,"warm":0.4,"creamy":0.2}'::jsonb, '#9A6A45'),
  ('b7a0b6d3-163c-5e3b-b96a-49d546c4b876', 'cacao', 'Cacao', 'material', 'gourmand', array['cocoa', 'chocolate', 'dark chocolate']::text[], 'Dark, bitter and powdery, more like cocoa powder than a milk chocolate bar.', 'Extracted from roasted cocoa beans as an absolute or CO2 extract, often reinforced with synthetic notes.', 'Adds a dark, bittersweet depth that keeps gourmands from tipping into pure sugar.', 'both', 'base', '{"sweet":0.5,"earthy":0.4,"warm":0.4,"powdery":0.2}'::jsonb, '#5A3A2E'),
  ('a8e163c0-a50c-57f4-8428-345826e48e25', 'coffee', 'Coffee', 'material', 'gourmand', array['coffee bean', 'espresso']::text[], 'Roasted, bitter and warm, like freshly ground beans.', 'CO2-extracted from roasted coffee beans, often supported by synthetic roasted notes.', 'Adds a dark, roasted bitterness that pairs well with vanilla, cardamom and woods.', 'both', 'heart', '{"warm":0.6,"earthy":0.4,"sweet":0.2,"smoky":0.2}'::jsonb, '#4E3A2E'),
  ('c401edc5-8dfd-5ee2-8724-1fc65f7c2b19', 'honey', 'Honey', 'accord', 'gourmand', array['beeswax']::text[], 'Sweet, warm and waxy with a faintly animal edge. Overdone, it can smell a bit like urine, which perfumers occasionally use on purpose.', 'Beeswax absolute brings a natural honey character, while synthetics such as phenylacetic acid add the sticky sweetness.', 'Adds a golden, slightly animalic sweetness to florals, tobaccos and ambers.', 'both', 'base', '{"sweet":0.8,"warm":0.5,"floral":0.2}'::jsonb, '#C1913E'),
  ('7ab6bfca-77a2-571d-ac60-e14b9e183794', 'almond', 'Almond', 'accord', 'gourmand', array['bitter almond', 'marzipan']::text[], 'Sweet, nutty and cherry-like, like marzipan or almond extract in a cake.', 'Built around benzaldehyde, the molecule that gives bitter almond and cherry their shared smell. Natural bitter almond oil is rarely used because it must first be stripped of toxic compounds.', 'Adds a soft, nutty sweetness that sits well with heliotrope, tonka and cherry.', 'synthetic', 'heart', '{"sweet":0.6,"creamy":0.3,"powdery":0.2}'::jsonb, '#D8C2A0'),
  ('bba009a6-2a8b-5098-9e81-2566748c7990', 'pistachio', 'Pistachio', 'accord', 'gourmand', '{}'::text[], 'Creamy, nutty and buttery, like pistachio gelato.', 'An accord of nutty, milky and creamy synthetic molecules.', 'Adds a soft, savory-sweet creaminess that is less sugary than most gourmand notes.', 'synthetic', 'base', '{"creamy":0.6,"sweet":0.5,"green":0.2}'::jsonb, '#A8B07A'),
  ('1b8e753b-0aec-5326-bc07-0fc1f37eddfd', 'rum', 'Rum', 'accord', 'gourmand', array['rhum', 'dark rum']::text[], 'Boozy, sweet and warm, like a glass of dark rum with a hint of molasses.', 'An accord, sometimes including rum absolute or rum ethers, combined with sweet and woody synthetics.', 'Adds a boozy warmth that pairs well with tobacco, vanilla and spice.', 'both', 'heart', '{"warm":0.6,"sweet":0.5}'::jsonb, '#7A4A2E'),
  ('32bb83c2-3699-5b04-8a59-a15bdcc85d39', 'milk', 'Milk', 'accord', 'gourmand', array['milky', 'lactonic', 'steamed milk']::text[], 'Soft, creamy and comforting, like warm milk or the smell of a baby’s head.', 'An accord built on lactones, the same family of molecules behind peach and coconut notes.', 'Adds a gentle, creamy softness to gourmands, florals and woods.', 'synthetic', 'base', '{"creamy":0.8,"sweet":0.3,"clean":0.2}'::jsonb, '#EAE2D2'),
  ('53c80cd4-724e-5cab-b492-cdc55654dd64', 'cedarwood', 'Cedarwood', 'material', 'woody', array['cedar', 'virginia cedar', 'atlas cedar']::text[], 'Dry, clean and woody, like pencil shavings or the inside of a cedar chest.', 'Steam-distilled from cedar wood. Virginia and Texas cedar smell like pencils, while Atlas cedar from Morocco is softer and more balsamic.', 'Gives structure, dryness and staying power. One of the most common base notes in perfumery.', 'natural', 'base', '{"woody":0.9,"clean":0.2}'::jsonb, '#9A7A58'),
  ('16ffd402-3d25-534e-922b-2c76becb3e7b', 'sandalwood', 'Sandalwood', 'material', 'woody', array['santal', 'mysore sandalwood', 'santalum']::text[], 'Creamy, smooth and milky wood. Soft and warm rather than dry.', 'Steam-distilled from the heartwood of sandalwood trees. Indian sandalwood was badly overharvested, so most of it now comes from Australian plantations or is rebuilt with synthetics.', 'Adds a creamy, soft woodiness that rounds out a fragrance and lingers for hours.', 'both', 'base', '{"woody":0.7,"creamy":0.7,"warm":0.3}'::jsonb, '#B8956A'),
  ('e28ed2cf-7e7c-589b-a9ac-bfb584f7a0cd', 'vetiver', 'Vetiver', 'material', 'woody', array['khus', 'khus khus', 'vetyver']::text[], 'Earthy, woody and a little smoky, with a grassy, rooty edge like wet soil around tree roots.', 'Steam-distilled from the roots of a tropical grass grown mostly in Haiti, Java and India. Each origin differs, from clean and grapefruit-like to dark and smoky.', 'Adds a dry, earthy polish and is the backbone of many fresh woody fragrances.', 'natural', 'base', '{"woody":0.7,"earthy":0.6,"green":0.3,"smoky":0.2}'::jsonb, '#6B6A45'),
  ('764f433e-c0bd-52f2-9e4e-632769cbe2b4', 'guaiac-wood', 'Guaiac wood', 'material', 'woody', array['guaiacwood', 'gaiac']::text[], 'Smoky, faintly rosy wood with a hint of tar, like a campfire built from good furniture.', 'Steam-distilled from the wood of a tree that grows in the dry Gran Chaco region of Paraguay and Argentina.', 'Adds a smooth, smoky woodiness that sits well with rose, oud and leather.', 'natural', 'base', '{"woody":0.7,"smoky":0.5,"warm":0.3}'::jsonb, '#7A5A45'),
  ('dde4f960-47a9-5bc0-b21b-196f5ed535f6', 'hinoki', 'Hinoki', 'material', 'woody', array['japanese cypress', 'hinoki cypress']::text[], 'Clean, lemony and resinous wood, like a Japanese wooden bathtub or a freshly planed board.', 'Steam-distilled from the wood of the Japanese cypress tree.', 'Adds a bright, clean woodiness, popular in calm, minimal compositions.', 'natural', 'base', '{"woody":0.7,"fresh":0.4,"clean":0.3}'::jsonb, '#C2A880'),
  ('95bb95e8-49a2-527a-83ea-113554fc5507', 'cypress', 'Cypress', 'material', 'woody', '{}'::text[], 'Green, resinous and dry, like pine needles but softer and more herbal.', 'Steam-distilled from the needles and twigs of the Mediterranean cypress.', 'Adds a dry, green woodiness that bridges aromatic openings and woody bases.', 'natural', 'heart', '{"woody":0.6,"green":0.5,"fresh":0.3}'::jsonb, '#5E6E55'),
  ('e2a405ce-3f21-562c-9a61-9c4119da67b5', 'pine', 'Pine', 'material', 'woody', array['pine needle', 'pine needles', 'fir needle']::text[], 'Sharp, resinous and green, like a walk through a pine forest or the corner where the tree stands in December.', 'Steam-distilled from pine needles and twigs. Fir and other conifer oils are often used alongside it.', 'Adds a cold, outdoorsy freshness to aromatic and woody fragrances.', 'natural', 'top', '{"woody":0.6,"fresh":0.6,"green":0.4}'::jsonb, '#4E6A4E'),
  ('c0c042d9-f5d8-56e2-84d6-8ce8d4059581', 'papyrus', 'Papyrus', 'material', 'woody', array['cypriol', 'nagarmotha']::text[], 'Dry, smoky and slightly leathery wood with an earthy edge.', 'True papyrus oil is rare. Many papyrus notes use cypriol, the root oil of a related sedge from India, along with woody synthetics.', 'Adds a dry, smoky texture to woods and leathers.', 'both', 'base', '{"woody":0.7,"smoky":0.4,"earthy":0.3}'::jsonb, '#8A7A5E'),
  ('783b4c29-41e7-52cc-b6fe-82ae408eaa64', 'cashmeran', 'Cashmeran', 'material', 'woody', array['cashmere wood', 'blonde woods']::text[], 'Soft, musky and woody, like a warm cashmere sweater. A little spicy, a little fluffy.', 'A synthetic molecule first made in the 1970s. Despite the name, it has nothing to do with cashmere wool.', 'Adds a cozy, diffusive warmth that makes woods and musks feel soft and touchable.', 'synthetic', 'base', '{"woody":0.5,"warm":0.5,"powdery":0.3}'::jsonb, '#B5A08A'),
  ('851f00bb-5e83-544b-96a5-e881b0009fe4', 'iso-e-super', 'Iso E Super', 'material', 'woody', array['iso e', 'ise']::text[], 'Soft, velvety woods with a faint cedar and amber glow. Some people find it radiant; others can barely smell it.', 'A synthetic woody-amber molecule from the 1970s. It is used everywhere, from tiny traces to huge doses, and is one of the most common materials in modern perfumery.', 'Adds a smooth, airy woodiness and makes everything around it feel bigger and more diffusive.', 'synthetic', 'base', '{"woody":0.7,"warm":0.4,"clean":0.2}'::jsonb, '#B3A58A'),
  ('d64746f6-2eac-5b6f-91aa-393526b0097a', 'oud', 'Oud', 'material', 'woody', array['agarwood', 'oudh', 'aoud', 'oud oil', 'agar']::text[], 'Dark, rich wood with medicinal, smoky and sometimes barnyard sides. Real oud can be very different from the oud notes in most fragrances.', 'Forms in the heartwood of agar trees infected with a mold, and is distilled from that resin-soaked wood. Natural oud is rare and costly, so most perfumes use accords built from woods, leather notes and synthetics.', 'Adds depth, darkness and a slightly animalic woodiness. Pairs classically with rose and saffron.', 'both', 'base', '{"woody":0.8,"smoky":0.4,"earthy":0.3,"warm":0.3}'::jsonb, '#4A3A30'),
  ('4ef2704d-f6ac-5392-a8af-35420084dea8', 'birch', 'Birch', 'material', 'woody', array['birch wood', 'birch leaf']::text[], 'Pale, fresh wood with a faint leathery, smoky edge, like birch logs stacked by a fireplace.', 'Birch leaf and bud oils exist, but most birch notes are blends of light woods with a little birch tar.', 'Adds a cool, slightly smoky woodiness that leans toward leather.', 'both', 'base', '{"woody":0.7,"smoky":0.3,"fresh":0.2}'::jsonb, '#C3B8A0'),
  ('cd8d84b5-7f47-5721-92ce-f86127522fec', 'patchouli', 'Patchouli', 'material', 'earthy', array['patchouly', 'pachouli']::text[], 'Earthy, dark and woody with a sweet, almost chocolatey depth. Damp forest floor meets an old leather-bound book.', 'Steam-distilled from dried, lightly fermented patchouli leaves, mostly from Indonesia. Modern fractions remove the earthiest parts for a cleaner, woodier patchouli.', 'Gives depth, earthiness and long-lasting structure. A pillar of chypres and many ambers.', 'natural', 'base', '{"earthy":0.8,"woody":0.5,"warm":0.3,"sweet":0.2}'::jsonb, '#5A4A3A'),
  ('8aed9cad-c47f-5e0f-b338-766e6338e04c', 'oakmoss', 'Oakmoss', 'material', 'earthy', array['oak moss', 'mousse de chene', 'treemoss']::text[], 'Damp, mossy and inky, like a forest floor after rain, with a slightly salty, leathery undertone.', 'Extracted from a lichen that grows on oak trees. Safety rules now limit it heavily, so modern oakmoss is usually treated to remove allergens or replaced with synthetics.', 'Gives a dark, bitter, earthy depth. The backbone of chypres and classic fougères.', 'both', 'base', '{"earthy":0.8,"green":0.4,"woody":0.3}'::jsonb, '#5E6A4E'),
  ('9273e691-9f5d-5b50-8190-f9a62fd386c1', 'hay', 'Hay', 'accord', 'earthy', array['dried grass', 'hay absolute']::text[], 'Warm, dry and sweet, like a barn full of dried grass at the end of summer.', 'An accord built around coumarin, sometimes with hay absolute, which is extracted from dried grasses.', 'Adds a sunny, sweet dryness that softens aromatic and tobacco compositions.', 'both', 'heart', '{"earthy":0.4,"sweet":0.4,"warm":0.4,"green":0.2}'::jsonb, '#BFA46A'),
  ('5bd91c7e-2383-5703-9f38-14f5761a7011', 'amber', 'Amber', 'accord', 'resinous', array['ambre', 'amber accord']::text[], 'Warm, sweet and resinous, a golden glow of vanilla, resins and a little powder. Nothing to do with the fossil resin in jewelry.', 'A fantasy accord with no single natural source, usually built from labdanum, benzoin and vanilla, plus other resins or synthetics.', 'Gives warmth, sweetness and long-lasting depth. The core of the amber family.', 'both', 'base', '{"warm":0.9,"sweet":0.5,"powdery":0.2}'::jsonb, '#B07A3A'),
  ('f22b7965-f2e6-5fb6-be29-afc89ff7f3e4', 'labdanum', 'Labdanum', 'material', 'resinous', array['cistus', 'rockrose', 'ciste']::text[], 'Rich, leathery and ambery, with a slightly animalic, honeyed depth.', 'A sticky resin from the rockrose shrub of the Mediterranean, used as a resinoid, absolute or oil. Shepherds once combed it out of the beards of goats that grazed on the plants.', 'The heart of most amber accords and a key part of chypres. Adds warmth and depth with a slight leathery edge.', 'natural', 'base', '{"warm":0.8,"sweet":0.3,"earthy":0.2,"smoky":0.2}'::jsonb, '#7A4E30'),
  ('c6f02e90-77c2-5529-ba49-9122351a1014', 'benzoin', 'Benzoin', 'material', 'resinous', array['siam benzoin', 'sumatra benzoin', 'gum benjamin']::text[], 'Sweet, warm and vanilla-like with a soft balsamic edge. Cozy and a little powdery.', 'A resin tapped from trees in Southeast Asia, usually used as a resinoid. Siam benzoin is sweeter and more vanilla-like than the Sumatra type.', 'Adds a sweet, balsamic warmth to amber and gourmand bases.', 'natural', 'base', '{"sweet":0.7,"warm":0.7,"powdery":0.3}'::jsonb, '#B08A5A'),
  ('91479fd3-d0f6-5164-9f9d-d65d347cebc5', 'frankincense', 'Frankincense', 'material', 'resinous', array['olibanum', 'boswellia']::text[], 'Fresh, lemony and peppery resin with a cool, smoky smoothness. Brighter than most people expect.', 'A resin tapped from boswellia trees in Oman, Somalia and nearby regions, steam-distilled into an oil or extracted as a resinoid.', 'Adds a cool, airy smokiness, the backbone of most incense accords.', 'natural', 'base', '{"smoky":0.5,"fresh":0.4,"woody":0.3,"spicy":0.2}'::jsonb, '#A89F84'),
  ('fa2cc4b5-e6ba-51e5-99e8-5eef4fdfb33c', 'myrrh', 'Myrrh', 'material', 'resinous', '{}'::text[], 'Bitter, resinous and earthy, with a mushroomy, slightly medicinal sweetness.', 'A resin from commiphora trees in the Horn of Africa and Arabia, used as an oil, resinoid or absolute.', 'Adds a dark, bittersweet resinous depth to incense, amber and rose compositions.', 'natural', 'base', '{"warm":0.5,"earthy":0.4,"smoky":0.3,"spicy":0.2}'::jsonb, '#8A5E3E'),
  ('769d3721-765b-5d43-869d-c3503fd27d6b', 'opoponax', 'Opoponax', 'material', 'resinous', array['opopanax', 'sweet myrrh']::text[], 'Sweet, warm and balsamic, like a softer, honeyed myrrh.', 'A resin from a tree closely related to myrrh, used as a resinoid or oil.', 'Adds a rich, sweet resinous warmth, common in amber bases.', 'natural', 'base', '{"warm":0.7,"sweet":0.5,"powdery":0.2}'::jsonb, '#9A6E45'),
  ('04e7f7e7-bd32-5fd8-b2ff-3a8433cd0441', 'ambroxan', 'Ambroxan', 'material', 'resinous', array['ambrox', 'ambroxide']::text[], 'Clean, warm and slightly salty, like skin after a day at the beach. Some people barely smell it; others find it loud.', 'A synthetic molecule usually made from sclareol, a component of clary sage, created to reproduce one facet of natural ambergris.', 'Adds a radiant, long-lasting warmth with a mineral glow. A defining note of many modern fresh woody fragrances.', 'synthetic', 'base', '{"warm":0.5,"clean":0.5,"woody":0.4}'::jsonb, '#C2B49A'),
  ('4a3392e4-1a7d-547f-8465-e6e14cbfac59', 'ambergris', 'Ambergris', 'accord', 'resinous', array['ambre gris', 'grey amber']::text[], 'Salty, musky and warm with a faint marine, tobacco-like sweetness. Hard to describe, easy to like.', 'Natural ambergris forms in the gut of sperm whales and ages for years at sea. It is rare and restricted in many countries, so perfume ambergris is almost always an accord built on ambroxan and related molecules.', 'Adds a glowing, salty warmth that makes a fragrance feel like skin.', 'both', 'base', '{"warm":0.6,"clean":0.3,"fresh":0.2,"woody":0.2}'::jsonb, '#B8AE98'),
  ('7a58cf9c-2ec3-5490-a575-515ec709a756', 'elemi', 'Elemi', 'material', 'resinous', '{}'::text[], 'Fresh, lemony and peppery resin, like frankincense with extra citrus.', 'A resin from a tree native to the Philippines, steam-distilled into an oil.', 'Adds a bright, resinous sparkle to openings, a clean bridge into incense and woods.', 'natural', 'top', '{"fresh":0.6,"spicy":0.3,"woody":0.2}'::jsonb, '#C4B98A'),
  ('f4db931d-b2c3-5996-9db1-0cafe5499223', 'styrax', 'Styrax', 'material', 'resinous', array['storax', 'liquidambar']::text[], 'Balsamic, smoky and leathery with a hint of cinnamon, like an old leather armchair near a fire.', 'A balsam from sweetgum trees, used as a resinoid or oil.', 'Adds a smoky, leathery sweetness to amber and leather bases.', 'natural', 'base', '{"warm":0.6,"smoky":0.4,"sweet":0.3}'::jsonb, '#6E4E3A'),
  ('adeaf7c3-8e72-57fd-a53a-9bdfbaa7afa4', 'musk', 'Musk', 'material', 'musk', array['white musk', 'clean musk', 'musks']::text[], 'Soft, clean and skin-like, like fresh laundry or warm skin. Some people cannot smell certain musks at all.', 'Musk once came from the musk deer, but it was replaced by synthetic musks for ethical and legal reasons. A few plant materials, such as ambrette seed, also smell musky.', 'Adds softness, diffusion and staying power, and makes other notes feel smoother.', 'both', 'base', '{"clean":0.6,"warm":0.4,"powdery":0.3}'::jsonb, '#D7CEC2'),
  ('1a08053c-6dcd-5862-9e55-6ff138a8dc4e', 'ambrette', 'Ambrette', 'material', 'musk', array['ambrette seed', 'musk mallow']::text[], 'Soft and musky with a faint pear-like fruitiness and a warm, skin-like quality.', 'Steam-distilled or CO2-extracted from the seeds of a plant in the hibiscus family, one of the few natural musks from plants.', 'Adds a natural, velvety muskiness that softens florals and woods.', 'natural', 'base', '{"warm":0.5,"fruity":0.3,"clean":0.3,"powdery":0.2}'::jsonb, '#C7B79A'),
  ('9a1ebd1a-0835-5da3-89c4-10f5e5fd5133', 'aldehydes', 'Aldehydes', 'material', 'musk', array['aldehyde', 'fatty aldehydes']::text[], 'Bright, soapy and fizzy, like crisp linen or a snuffed candle. Some people smell champagne bubbles, others smell an iron.', 'A family of synthetic molecules, some also found in nature in citrus peel and other plants. Fatty aldehydes became famous in early twentieth-century florals.', 'Adds lift, sparkle and a clean, soapy brightness to the opening.', 'synthetic', 'top', '{"clean":0.8,"fresh":0.5,"powdery":0.2}'::jsonb, '#E2E0D2'),
  ('efae7e9d-64d2-545a-b41e-3fc2986f615c', 'leather', 'Leather', 'accord', 'leather', array['cuir']::text[], 'Smoky, dry and slightly animalic, like a well-worn leather jacket or a saddle.', 'An accord, since leather itself is not extracted. Built from birch tar, quinolines, saffron-like molecules and other synthetics.', 'Adds a dark, textured warmth to woody, floral and smoky compositions.', 'both', 'base', '{"smoky":0.5,"warm":0.4,"earthy":0.3,"woody":0.2}'::jsonb, '#6A4A3A'),
  ('d09b2c1d-c30b-596e-9d45-614e6bfb2fd6', 'suede', 'Suede', 'accord', 'leather', array['daim']::text[], 'Soft, powdery and gentle leather, like the inside of a suede glove.', 'An accord of soft leathery synthetics, often with iris, musks and saffron notes.', 'Adds a velvety, skin-close leather without the smoke.', 'synthetic', 'base', '{"powdery":0.5,"warm":0.4,"smoky":0.2}'::jsonb, '#A8896A'),
  ('43225eda-fbc0-5fa2-85b4-1db15407674a', 'birch-tar', 'Birch tar', 'material', 'leather', array['rectified birch tar']::text[], 'Intensely smoky and tarry, like a campfire or a road being resurfaced.', 'Made by dry distillation of birch bark, then purified for perfume use.', 'The classic source of smoky leather. A small amount adds a lot of character.', 'natural', 'base', '{"smoky":0.9,"woody":0.3}'::jsonb, '#3E322C'),
  ('8c869c5f-84d2-590f-96b8-6e88b6a8a2b6', 'tobacco', 'Tobacco', 'material', 'smoky', array['tobacco leaf', 'pipe tobacco', 'tobacco absolute']::text[], 'Sweet, dry and honeyed, like an unlit pouch of pipe tobacco rather than a lit cigarette.', 'Tobacco absolute is extracted from cured tobacco leaves and is often supported by synthetic notes.', 'Adds a warm, sweet, slightly smoky depth, often alongside vanilla, rum and honey.', 'both', 'base', '{"warm":0.6,"sweet":0.4,"earthy":0.3,"smoky":0.3}'::jsonb, '#8A5E3A'),
  ('ff51dd39-0c8f-5d57-9b8c-4378d52b0c11', 'incense', 'Incense', 'accord', 'smoky', array['church incense', 'temple incense']::text[], 'Smoky, resinous and cool, like a stone church after a service.', 'An accord built around frankincense, myrrh and other resins, often with smoky and mineral synthetics.', 'Adds a cool, contemplative smokiness to woods, ambers and florals.', 'both', 'base', '{"smoky":0.8,"woody":0.4,"fresh":0.2}'::jsonb, '#7A7470'),
  ('77e93113-f47b-5f42-b4ef-aaa96ef42ecc', 'cade', 'Cade', 'material', 'smoky', array['cade oil', 'juniper tar']::text[], 'Dark, smoky and tarry, like a smoldering campfire or smoked meat.', 'Made by dry distillation of the wood of a juniper shrub that grows around the Mediterranean.', 'Adds a raw, smoky darkness to leathers and woods.', 'natural', 'base', '{"smoky":0.9,"woody":0.4}'::jsonb, '#4A3E36'),
  ('86fcbd2c-0e2d-5dea-a353-1f1695c41ed0', 'black-tea', 'Black tea', 'accord', 'tea', array['tea', 'darjeeling']::text[], 'Dry, slightly smoky and bitter, like a freshly brewed cup of strong black tea.', 'An accord of tea-like synthetics, sometimes with tea absolute, which is extracted from dried leaves but rarely used.', 'Adds a dry, slightly tannic warmth that grounds citrus and florals.', 'both', 'heart', '{"woody":0.3,"earthy":0.3,"warm":0.3,"smoky":0.2}'::jsonb, '#6A4E3A'),
  ('a6df30bd-d8b5-5eb6-8ba0-50f73607ed19', 'green-tea', 'Green tea', 'accord', 'tea', '{}'::text[], 'Light, fresh and slightly bitter, like steam rising from a cup of green tea.', 'An accord built mostly from hedione and other fresh, green synthetic molecules.', 'Adds a calm, transparent freshness, popular in light summer fragrances.', 'synthetic', 'heart', '{"fresh":0.6,"green":0.5,"clean":0.3}'::jsonb, '#9AA77A'),
  ('0c0fd0d1-de9b-545e-8d57-e6ebf06ee2a0', 'matcha', 'Matcha', 'accord', 'tea', array['matcha tea']::text[], 'Rich, creamy and grassy, like a freshly whisked bowl of matcha.', 'An accord combining green tea notes with milky, powdery and grassy synthetics.', 'Adds a soft, creamy greenness that sits between fresh and gourmand.', 'synthetic', 'heart', '{"green":0.7,"creamy":0.4,"earthy":0.2}'::jsonb, '#7E9A5A'),
  ('241d3aa1-52a1-5320-a962-b46617f3a372', 'lapsang-souchong', 'Lapsang souchong', 'accord', 'tea', array['lapsang', 'smoked tea']::text[], 'Smoky, resinous tea, like a cup brewed over a pine campfire.', 'An accord of black tea notes with smoky materials such as birch tar, cade or guaiacol.', 'Adds a dry, smoky warmth that links tea, leather and wood notes.', 'both', 'heart', '{"smoky":0.7,"woody":0.4,"warm":0.3}'::jsonb, '#5A4A3E'),
  ('11bf03d7-3899-5f17-8164-28ac7d506544', 'mate', 'Maté', 'material', 'tea', array['mate', 'yerba mate']::text[], 'Grassy, slightly smoky and bitter, like the South American herbal tea brewed in a gourd.', 'Maté absolute is extracted from the dried leaves of the yerba mate plant and used in small amounts.', 'Adds a green, hay-like bitterness to aromatic and woody compositions.', 'natural', 'heart', '{"green":0.6,"earthy":0.4,"smoky":0.2}'::jsonb, '#7A7A4E'),
  ('9b87900f-e05d-5d1d-89ac-7adbbce171b3', 'soapy', 'Soapy', 'descriptor', 'musk', array['soap', 'clean soap']::text[], 'Clean, waxy and bubbly, like a fresh bar of white soap.', 'Usually perceived from aldehydes, clean musks and floral molecules from the orange blossom and lily of the valley families. Many of these also scent real soap, so the link is partly learned.', 'Makes a fragrance read as clean, freshly washed and well-groomed.', 'both', 'heart', '{"clean":0.9,"fresh":0.3,"powdery":0.2}'::jsonb, '#E4E1D6'),
  ('9996aa77-0352-5b0a-84ce-84d6b3bce598', 'laundry', 'Laundry', 'descriptor', 'musk', array['clean laundry', 'fresh laundry', 'detergent']::text[], 'Freshly washed sheets, or a towel straight out of the dryer.', 'Mostly white musks, aldehydes and fresh floral molecules, many of which are the same ones used to scent detergents and fabric softeners.', 'Gives a comforting, close-to-skin cleanliness that many people find easy to wear.', 'both', 'base', '{"clean":0.9,"fresh":0.4,"powdery":0.2}'::jsonb, '#DDE0DA'),
  ('0c1e7835-7fe4-5021-961f-f21f60077f88', 'metallic', 'Metallic', 'descriptor', 'mineral', array['metal', 'coin', 'steel']::text[], 'Cold, sharp and coin-like, like a handful of keys or a cold railing.', 'People often read aldehydes, some ozonic and green synthetics, and the rosy side of rose and geranium as metallic.', 'Adds a cool, modern edge that keeps sweet or floral compositions from feeling too soft.', 'both', 'heart', '{"fresh":0.5,"clean":0.3}'::jsonb, '#9AA0A3'),
  ('d66b4c9b-6643-59e8-b082-a0ac686bdf7b', 'mineral', 'Mineral', 'descriptor', 'mineral', array['stone', 'wet stone', 'flint']::text[], 'Cool and stony, like wet rocks or a pebble beach.', 'Usually perceived from ambroxan, geosmin, ozonic and salty notes, and certain smoky molecules that suggest struck flint.', 'Adds a cool, dry texture that makes fresh fragrances feel less sweet and more natural.', 'both', 'heart', '{"fresh":0.5,"earthy":0.3,"clean":0.3}'::jsonb, '#A3A6A0'),
  ('55aebf64-cc55-5325-9f22-929d05c9c1b8', 'ink', 'Ink', 'descriptor', 'mineral', array['inky']::text[], 'Slightly bitter, metallic and powdery, like fountain pen ink or a fresh newspaper.', 'Usually perceived from combinations of iris, oakmoss, saffron, cumin, smoky woods and aldehydes.', 'Adds a dark, intellectual dryness that reads as unusual and a little moody.', 'both', 'heart', '{"earthy":0.4,"smoky":0.3,"powdery":0.2}'::jsonb, '#4A5060'),
  ('07880cb6-3c10-51b5-a8ab-9447be5ff715', 'ozonic', 'Ozonic', 'descriptor', 'marine', array['ozone', 'airy', 'fresh air']::text[], 'The cool, electric air before a storm, or sheets dried outside on a windy day.', 'Usually perceived from ozonic synthetics such as helional, along with calone and certain aldehydes.', 'Adds a bright, airy sense of space to fresh compositions.', 'both', 'top', '{"fresh":0.8,"clean":0.5}'::jsonb, '#B8C8CC'),
  ('0fec2105-a9cf-57af-b819-88525425a8c9', 'boozy', 'Boozy', 'descriptor', 'gourmand', array['alcoholic', 'liqueur', 'cognac', 'whisky']::text[], 'Sweet and warm, like a dessert soaked in rum or a glass of cognac.', 'Usually perceived from rum, cognac or whisky accords, fruity esters, and some resins and tonka-vanilla blends.', 'Adds a warm, slightly decadent glow, especially in evening fragrances.', 'both', 'heart', '{"warm":0.6,"sweet":0.5}'::jsonb, '#8A5A3A'),
  ('cc0f54dc-eeeb-5de4-a5e9-479896638d2a', 'animalic', 'Animalic', 'descriptor', 'leather', array['dirty', 'skanky']::text[], 'Warm, intimate and a bit dirty, like skin, sweat, fur or a horse stable.', 'Usually perceived from indolic florals like jasmine and orange blossom, synthetic stand-ins for civet and castoreum, cumin, labdanum, or musks that suggest the body.', 'Adds warmth, sensuality and a lived-in realism. In larger doses it divides opinion fast.', 'both', 'base', '{"warm":0.6,"earthy":0.4}'::jsonb, '#6A5048'),
  ('405b3f50-1aa5-555d-9252-edba4659f552', 'waxy', 'Waxy', 'descriptor', 'floral', array['candle wax', 'candle']::text[], 'Smooth and dense, like a candle or the thick petals of a white flower.', 'Often perceived from aldehydes, tuberose, gardenia, orris or beeswax absolute, which all share a candle-like texture.', 'Adds body and a smooth, almost tactile texture to florals.', 'both', 'heart', '{"creamy":0.4,"clean":0.3,"floral":0.3}'::jsonb, '#E2D8BC'),
  ('811cc5c0-b2be-5f61-8b0f-5b46806198a0', 'fizzy', 'Fizzy', 'descriptor', 'citrus', array['sparkling', 'effervescent', 'soda']::text[], 'Bright and bubbly, like cracking open a can of soda.', 'Usually perceived from citrus oils, pink pepper, ginger and some aldehydes in the opening.', 'Makes an opening feel lively and carbonated. It rarely outlasts the first half hour.', 'both', 'top', '{"fresh":0.8,"fruity":0.2}'::jsonb, '#D6CF8E'),
  ('99fe935e-dfcc-53d4-ab36-3bd55e9b08be', 'sunscreen', 'Sunscreen', 'descriptor', 'marine', array['sun lotion', 'suntan lotion', 'sun cream', 'beachy']::text[], 'Creamy, sweet and slightly floral, like sun lotion warming on skin.', 'Usually perceived from salicylates (once common in sunscreens), coconut lactones, frangipani and ylang-ylang.', 'Adds a holiday-like, creamy warmth that many people find instantly nostalgic.', 'both', 'heart', '{"creamy":0.6,"sweet":0.3,"floral":0.3,"warm":0.2}'::jsonb, '#E6D4B0'),
  ('22ccc20f-0530-5f7a-bd39-05003221547e', 'powdery', 'Powdery', 'descriptor', 'floral', array['powder', 'talc', 'baby powder', 'makeup']::text[], 'Soft and dry, like baby powder or a makeup compact.', 'Usually perceived from iris, violet, heliotrope, musks, vanillin and coumarin, which are also common in cosmetics, so the link is partly learned.', 'Adds softness and a gentle, old-fashioned elegance. Some people love it; others call it "grandma".', 'both', 'base', '{"powdery":0.9,"sweet":0.3,"floral":0.2}'::jsonb, '#D8CDD0'),
  ('e5a25774-b82b-5157-8314-86378f1adf07', 'sichuan-pepper', 'Sichuan pepper', 'material', 'spice', array['szechuan pepper', 'timut pepper', 'sansho']::text[], 'Peppery and citrusy at once, closer to grapefruit peel and lemon grass than to black pepper, with a faint tingling brightness.', 'The dried husks of several Zanthoxylum shrubs, a relative of citrus rather than true pepper. Perfumers use the essential oil or a CO2 extract, often supported by synthetic pepper notes.', 'Adds a zesty, slightly fizzy spice that makes fresh openings feel sharper and more modern.', 'both', 'top', '{"spicy":0.7,"fresh":0.5,"fruity":0.1}'::jsonb, '#9C6B4E'),
  ('b1e97360-2c00-55fd-ba47-b763af4884a7', 'hedione', 'Hedione', 'material', 'floral', array['methyl dihydrojasmonate', 'mdj']::text[], 'Airy, watery jasmine with a hint of citrus, more like the air around a flowering bush than the flower itself.', 'A synthetic molecule related to a compound found in jasmine, introduced to perfumery in the 1960s. Today it sits in a huge share of fine fragrances at some level.', 'Adds space and diffusion: it makes citrus and florals feel bigger, softer and more transparent without reading as a separate note.', 'synthetic', 'heart', '{"floral":0.5,"fresh":0.5,"clean":0.3}'::jsonb, '#D6D2B8'),
  ('09d7e179-a778-544d-90b5-fb5c9d1ce9e4', 'lotus', 'Lotus', 'accord', 'floral', array['lotus flower', 'water lily', 'nymphaea']::text[], 'A pale, watery floral, a little green and a little powdery, like a pond flower on a cool morning.', 'Lotus extracts exist but are rare in perfumery. The note is almost always an accord built from aquatic, green and soft floral molecules.', 'Gives a calm, watery floral tone that sits between fresh and floral without much sweetness.', 'both', 'heart', '{"floral":0.5,"fresh":0.4,"green":0.3,"clean":0.2}'::jsonb, '#C9B9C4'),
  ('271ba4a7-81b4-5ef7-a5c6-a6cc96101413', 'green-leaves', 'Green leaves', 'accord', 'green', array['green notes', 'leaves', 'green leaf', 'leafy notes']::text[], 'Crushed leaves and snapped stems: sappy, slightly bitter and very fresh.', 'An accord built mostly from synthetic leaf-alcohol type molecules (the smell of freshly broken greenery), sometimes with galbanum or violet leaf.', 'Adds an outdoorsy, sappy lift to the opening and keeps sweet or aquatic notes from feeling flat.', 'both', 'top', '{"green":0.8,"fresh":0.5}'::jsonb, '#7E9A6A'),
  ('8021f18e-a257-5dc3-a57f-6b33aac14ac4', 'coriander', 'Coriander', 'material', 'spice', array['coriander seed', 'cilantro seed']::text[], 'Warm, gently spicy and a little citrusy, with a soft woody edge. The seed smells nothing like the soapy fresh leaf.', 'Steam-distilled from the dried seeds of the coriander plant, grown widely in Russia, Ukraine and India.', 'Bridges citrus and spice in the opening and gives aromatic fougeres a soft, slightly peppery warmth.', 'natural', 'top', '{"spicy":0.5,"fresh":0.4,"woody":0.2}'::jsonb, '#A8925E'),
  ('c27f9ab1-29e4-54cf-88b1-21078d179b35', 'amberwood', 'Amberwood', 'accord', 'woody', array['ambery woods', 'amber wood', 'amberwoods', 'ambery wood']::text[], 'Dry, warm and slightly scratchy woods with a mineral, ambery glow. Loud and very long-lasting.', 'A modern accord built from powerful synthetic woody-amber molecules, often alongside ambroxan. Not related to amber resin.', 'Gives a radiant, persistent woody base that carries a fragrance for hours and adds a clean, dry sparkle.', 'synthetic', 'base', '{"woody":0.7,"warm":0.4,"clean":0.2}'::jsonb, '#A68A6B'),
  ('55104788-64d2-5ed9-8a73-89e03c31f392', 'white-woods', 'White woods', 'accord', 'woody', array['white wood', 'blond wood', 'pale woods']::text[], 'Soft, clean and slightly creamy wood, like freshly planed pale timber with no smoke or resin.', 'A perfumer accord rather than a single tree, usually built from synthetic woody molecules such as cedar-type and musky-woody materials.', 'Gives a smooth, light woody floor that lets louder notes above it take the spotlight.', 'synthetic', 'base', '{"woody":0.6,"clean":0.4,"creamy":0.2}'::jsonb, '#C9B89A'),
  ('55aa984d-ebf5-5aa7-9133-5967879bfffa', 'orchid', 'Orchid', 'accord', 'floral', array['vanilla orchid', 'cattleya orchid']::text[], 'A soft, creamy floral with a faint vanilla sweetness. Most orchids barely smell at all, so in perfume the word describes a mood more than a flower.', 'No orchid oil is produced for perfumery. The note is assembled from creamy, slightly powdery floral and vanillic molecules; vanilla itself is the cured pod of an orchid.', 'Rounds off brighter florals and gives a heart a plush, sweet texture without obvious fruit.', 'synthetic', 'heart', '{"floral":0.6,"creamy":0.3,"sweet":0.3,"powdery":0.2}'::jsonb, '#B48FA6'),
  ('9783d281-1e9e-5a52-b578-5166f8554728', 'freesia', 'Freesia', 'accord', 'floral', '{}'::text[], 'Light, airy and a little peppery-sweet, like a bunch of freesias in a cool room. Brighter and greener than rose.', 'Freesia flowers are not extracted commercially. Perfumers rebuild the scent with fresh floral aroma chemicals such as linalool and related molecules.', 'Adds lift and a clean, watery brightness to a floral heart.', 'synthetic', 'heart', '{"floral":0.6,"fresh":0.4,"clean":0.2}'::jsonb, '#B5A8C0'),
  ('0f35218f-0183-5dc3-b8da-89c5319f4e99', 'strawberry', 'Strawberry', 'accord', 'fruity', array['wild strawberry']::text[], 'Ripe, jammy red berry, somewhere between fresh strawberries and strawberry sweets.', 'Strawberries give no usable oil. The note is built from fruity esters and caramel-leaning molecules, often with a green or creamy twist to keep it from smelling like candy.', 'A playful, sweet fruit opening that reads young and cheerful.', 'synthetic', 'top', '{"fruity":0.8,"sweet":0.5}'::jsonb, '#B9636A'),
  ('c803d9ee-5d44-55b8-911d-1862436d8045', 'passion-fruit', 'Passion fruit', 'accord', 'fruity', array['passionfruit', 'purple passion fruit']::text[], 'Tart, tropical and juicy, with the slightly sulfurous tang you get from scooping out fresh passion fruit pulp.', 'Built from synthetic tropical-fruit molecules, including sulfur compounds used in tiny amounts. Natural extracts are rarely used in fine fragrance.', 'A loud, sunny fruit top note that gives a fragrance instant juiciness.', 'synthetic', 'top', '{"fruity":0.8,"sweet":0.3,"fresh":0.3}'::jsonb, '#A9824F'),
  ('31233916-6c7d-5538-8bc5-0f0d09034950', 'fir-resin', 'Fir resin', 'material', 'resinous', array['fir balsam', 'fir balsam absolute']::text[], 'Sweet, balsamic pine with a faintly jammy depth, like sticky sap on the trunk of a fir tree.', 'An oleoresin collected from the bark of fir trees and usually sold as an absolute. The needles give a separate, greener oil.', 'Adds a warm, resinous sweetness that bridges woods and ambers.', 'natural', 'base', '{"woody":0.5,"warm":0.4,"sweet":0.3,"green":0.2,"smoky":0.1}'::jsonb, '#7D6A47'),
  ('3a7d6351-63d0-5c5b-81f6-d0714daf99ec', 'dried-fruit', 'Dried fruit', 'accord', 'fruity', array['dried fruits', 'dates', 'raisins']::text[], 'Dense, sticky sweetness like dates, raisins and dried figs. More jam jar than orchard.', 'An accord rather than one material, built from fruity lactones and caramel-like molecules, sometimes with natural absolutes for depth.', 'Gives tobacco and amber compositions a rich, edible middle.', 'both', 'heart', '{"fruity":0.5,"sweet":0.6,"warm":0.4}'::jsonb, '#7A4B3B'),
  ('b9a51b11-ee0d-5d35-9d75-4ec0a88ea5ad', 'rosewood', 'Rosewood', 'material', 'woody', array['bois de rose']::text[], 'Soft, rosy wood with a slightly spicy, lavender-like freshness. Smoother and more floral than cedar.', 'Traditionally distilled from the Amazonian tree Aniba rosaeodora, now a protected species. Perfumes use certified oil or rebuild the effect around linalool, its main component.', 'A polished, gently floral wood that softens spice and darker woods.', 'both', 'heart', '{"woody":0.5,"floral":0.3,"fresh":0.2,"spicy":0.1}'::jsonb, '#965E50'),
  ('8512c747-62a6-50ac-ab36-711cc7504a85', 'green-mango', 'Green mango', 'accord', 'fruity', array['unripe mango', 'mango']::text[], 'Sour, leafy and a little resinous, like the skin of an unripe mango rather than the sweet orange flesh.', 'Built by the perfumer, usually from citrus, green and fruity molecules, since mango gives no usable essential oil.', 'A tart, juicy green opening that reads fruity without turning tropical or sugary.', 'synthetic', 'top', '{"fruity":0.6,"green":0.6,"fresh":0.5}'::jsonb, '#9DAA6A'),
  ('51bf13ed-8465-5f49-96f9-8a1fc4e1ecb2', 'sycamore', 'Sycamore', 'accord', 'woody', array['sycamore wood', 'sycamore fig wood']::text[], 'Dry, pale, slightly milky wood, like fresh-cut light timber.', 'A fantasy wood accord. Sycamore does not yield a perfume oil, so it is built from soft woody and musky materials.', 'A quiet, clean woody base that stays in the background.', 'synthetic', 'base', '{"woody":0.6,"clean":0.3,"creamy":0.2}'::jsonb, '#B9A88A'),
  ('86ee12a6-6947-55ee-97ad-2d056719bc2d', 'marshmallow', 'Marshmallow', 'accord', 'gourmand', array['guimauve']::text[], 'Soft, powdery sugar with a hint of vanilla and orange blossom, like a bag of fresh marshmallows.', 'A gourmand accord built from sweet molecules such as ethyl maltol, vanillin and heliotropin, often with a floral touch.', 'A fluffy, sugary softness that rounds off florals and makes a base feel cosy.', 'synthetic', 'base', '{"sweet":0.8,"creamy":0.5,"powdery":0.4}'::jsonb, '#E6D3CF'),
  ('8831d955-9896-5875-8b59-8f9b50d300b2', 'date', 'Date', 'accord', 'fruity', array['dates', 'date fruit']::text[], 'Dark, sticky and caramel-like, like a ripe Medjool date with a slightly winey edge.', 'An accord built from fruity, caramelic and lactonic molecules. Date fruit gives no perfume oil.', 'Adds a dense, dried-fruit sweetness that pairs with spice, amber and vanilla.', 'synthetic', 'heart', '{"sweet":0.7,"fruity":0.5,"warm":0.4}'::jsonb, '#7A4A2E'),
  ('0fa74d3a-966b-5111-b571-c79d1c52889b', 'rubber', 'Rubber', 'accord', 'leather', array['vulcanised rubber', 'tyre']::text[], 'Like a new bicycle inner tube or a box of rubber bands: slightly smoky, dense and a little sweet.', 'An accord, usually built from smoky, tarry and leathery materials such as birch tar or cade.', 'Gives an urban, industrial darkness and makes leather or tea notes feel unusual.', 'synthetic', 'heart', '{"smoky":0.6,"earthy":0.3,"warm":0.2}'::jsonb, '#3E3B38'),
  ('df4c76ed-fd39-5235-adc9-dde30c13cdd3', 'driftwood', 'Driftwood', 'accord', 'woody', array['drift wood']::text[], 'Sun-bleached, salty, dry wood, as if it had been lying on a beach for a summer.', 'A fantasy accord made from dry woody molecules, often with a mineral or ambery touch.', 'A light, dry woody base that suits aquatic and fresh compositions.', 'synthetic', 'base', '{"woody":0.6,"fresh":0.2,"clean":0.2}'::jsonb, '#A89A86'),
  ('5021ae92-718c-5543-a984-2a19b188d184', 'pimento', 'Pimento', 'material', 'spice', array['allspice', 'pimento berry']::text[], 'Warm and clove-like with a peppery, cinnamon-ish edge, like a pinch of ground allspice.', 'Steam-distilled from the dried berries (and sometimes leaves) of the Jamaican pimento tree.', 'Adds a warm, slightly medicinal spice that sits between clove and pepper.', 'natural', 'heart', '{"spicy":0.7,"warm":0.4,"woody":0.1}'::jsonb, '#8A5A3C'),
  ('1c86a1ff-950e-538d-8960-7aac9fd57b22', 'akigalawood', 'Akigalawood', 'material', 'woody', array['akigala wood']::text[], 'A peppery, slightly spicy woodiness, like patchouli with the earthy, damp side taken out.', 'A captive material made by treating patchouli oil with enzymes, which changes its character. Only available to one fragrance supplier.', 'Adds a dry, spicy woody depth to warm and gourmand bases.', 'both', 'base', '{"woody":0.6,"spicy":0.3,"earthy":0.2}'::jsonb, '#7E6A52');
insert into public.brands (id, slug, name, kind, country, city, founded_year, description, known_for, website_url, parent_company, wikidata_qid, data_source_id, source_url, is_demo) values
  ('94426ffc-26b4-5ba6-89ed-da666de3cd55', 'dior', 'Dior', 'designer', 'FR', 'Paris', 1946, 'The couture house Christian Dior opened in Paris in 1946 and launched its perfume arm, Parfums Christian Dior, the following year with Miss Dior. Today the fragrance business sits inside LVMH and runs one of the biggest masculine lines in the world. It also keeps an archive of classics that are reworked from time to time.', 'Polished blockbusters and long-running classics', 'https://www.dior.com', 'LVMH', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.dior.com', false),
  ('3b935de0-5e9c-5c37-a5f2-d6d6ade57c8a', 'chanel', 'Chanel', 'designer', 'FR', 'Paris', 1910, 'Gabrielle Chanel opened her first Paris shop in 1910 and launched N°5, her first perfume, in 1921. The company is privately held and makes its fragrances in-house, with a small line of in-house perfumers that has passed from Ernest Beaux to Henri Robert, Jacques Polge and Olivier Polge.', 'Aldehydic florals, clean woods, in-house perfumers', 'https://www.chanel.com', 'Chanel Limited (privately held)', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.chanel.com', false),
  ('531aa3f7-357c-5099-9164-8f3edaac55fc', 'giorgio-armani', 'Giorgio Armani', 'designer', 'IT', 'Milan', 1975, 'Giorgio Armani and Sergio Galeotti founded the Milan fashion company in 1975. Its fragrances are made under licence by L''Oréal, and the Acqua di Giò family has been one of the best-known fresh lines since the 1990s.', 'Aquatic freshness and soft, tailored woods', 'https://www.armani.com', 'Giorgio Armani S.p.A. (fragrances licensed to L''Oréal)', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.armani.com', false),
  ('aedf7762-e058-583d-b213-c57401794864', 'yves-saint-laurent', 'Yves Saint Laurent', 'designer', 'FR', 'Paris', 1961, 'Yves Saint Laurent and Pierre Bergé founded the couture house in Paris in 1961. The beauty and fragrance business has been owned by L''Oréal since 2008, while the fashion side belongs to Kering. Its perfume catalogue runs from Opium and Kouros to modern bestsellers such as Y and Black Opium.', 'Big, glossy modern bestsellers', 'https://www.yslbeauty.com', 'L''Oréal (YSL Beauté); the fashion house belongs to Kering', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.yslbeauty.com', false),
  ('37c2be55-c758-592c-a46f-9daee8a86d7e', 'hermes', 'Hermès', 'designer', 'FR', 'Paris', 1837, 'Thierry Hermès opened a harness workshop in Paris in 1837, and the family-controlled company later grew into leather goods, silk and perfume. It has kept an in-house perfumer since 2004, first Jean-Claude Ellena and then Christine Nagel, and its fragrances tend toward transparency rather than volume.', 'Airy, understated compositions with an in-house nose', 'https://www.hermes.com', 'Hermès International', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.hermes.com', false),
  ('f65bdbf9-1992-59a4-8a31-5258a0bfeb37', 'versace', 'Versace', 'designer', 'IT', 'Milan', 1978, 'Gianni Versace founded his Milan fashion house in 1978, and the Medusa head logo turns up on almost everything it makes, perfume bottles included. Its fragrances are produced under licence and lean toward bright, sweet, high-energy styles aimed at a young audience.', 'Loud, sweet and fresh crowd-pleasers', 'https://www.versace.com', 'Prada Group (since 2025); fragrances made under licence by EuroItalia', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.versace.com', false),
  ('f0054016-723d-582a-9fa2-9a72258e5fa2', 'jean-paul-gaultier', 'Jean Paul Gaultier', 'designer', 'FR', 'Paris', 1982, 'Jean Paul Gaultier showed his first collection in 1976 and set up his own Paris fashion company in 1982. The early fragrances, Le Male included, were launched under Shiseido''s Beauté Prestige International; Puig bought the brand and later took over the perfumes. The line is known for torso-shaped bottles packed in tins.', 'Torso bottles, lavender and vanilla', 'https://www.jeanpaulgaultier.com', 'Puig', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.jeanpaulgaultier.com', false),
  ('dbba5627-c5a6-5db7-aab0-59c631745827', 'rabanne', 'Rabanne', 'designer', 'FR', 'Paris', 1966, 'Paco Rabanne launched his Paris house in 1966 with dresses made of metal and plastic discs, and Puig has made the fragrances since the late 1960s and owns the brand. The house dropped "Paco" from its name in 2023. Its bestsellers come in bottles shaped like objects, from gold ingots to robots.', 'Novelty bottles and sweet, spicy mass hits', 'https://www.rabanne.com', 'Puig', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.rabanne.com', false),
  ('ef519ad7-5a37-5f8c-9043-a756961c6df7', 'prada', 'Prada', 'designer', 'IT', 'Milan', 1913, 'Mario Prada opened a leather goods shop in Milan in 1913. Since 2021 its fragrances have been made under licence by L''Oréal. The perfume line is known for clean, iris-heavy compositions, many of them by Daniela Andrier.', 'Powdery iris and soapy cleanliness', 'https://www.prada.com', 'Prada S.p.A. (fragrances licensed to L''Oréal)', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.prada.com', false),
  ('034b778a-6efa-5ae7-89ae-cff7fda7ec61', 'davidoff', 'Davidoff', 'mass', 'CH', 'Geneva', 1911, 'The Davidoff name goes back to a tobacco shop the Davidoff family opened in Geneva in 1911, later built into a cigar brand by Zino Davidoff. The fragrances are made under licence by Coty. Cool Water, from 1988, is by far the best known.', 'Affordable fresh aromatics', 'https://www.davidoff.com', 'Oettinger Davidoff AG (fragrances licensed to Coty)', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.davidoff.com', false),
  ('08b4fcd1-387a-5dea-88ca-4e7f32783cc4', 'nautica', 'Nautica', 'mass', 'US', 'New York', 1983, 'Designer David Chu founded Nautica in New York in 1983 as a sailing-inspired outerwear label. It is now owned by Authentic Brands Group, and its fragrances sell mostly through department stores, drugstores and discounters at low prices.', 'Cheap, cheerful aquatic freshies', 'https://www.nautica.com', 'Authentic Brands Group', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.nautica.com', false),
  ('145ed50c-1592-563f-810f-373d45c65e81', 'lancome', 'Lancôme', 'designer', 'FR', 'Paris', 1935, 'Armand Petitjean founded Lancôme in 1935, launching it with a set of perfumes, and L''Oréal bought the company in 1964. Its fragrance line ranges from the 1970s chypre Magie Noire to La Vie Est Belle, one of the best-selling feminine fragrances of the 2010s.', 'Gourmand florals and iris', 'https://www.lancome-usa.com', 'L''Oréal', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', 'https://www.lancome.com', false),
  ('4f5e7c17-6249-5c86-9421-15e05907d592', 'mugler', 'Mugler', 'designer', 'FR', 'Paris', 1974, 'Fashion house founded in Paris by designer Thierry Mugler in the 1970s. Its first fragrance, Angel (1992), is widely credited with launching the modern gourmand genre, and its perfumes have been part of L''Oréal since 2019.', 'Theatrical gourmands and star-shaped bottles', 'https://www.mugler.com', 'L''Oréal (fragrance and beauty)', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('f8c50fa4-85ac-59d6-9fa8-446b0751452b', 'carolina-herrera', 'Carolina Herrera', 'designer', 'US', 'New York', 1981, 'New York fashion house founded by Venezuelan-born designer Carolina Herrera in 1981. Its fragrances are produced by the Spanish group Puig, and the stiletto-bottled Good Girl line is its biggest perfume success.', 'Glossy evening florals and novelty bottles', 'https://www.carolinaherrera.com', 'Puig', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('b4311656-ee28-5610-b73c-be7b93b83653', 'viktor-rolf', 'Viktor&Rolf', 'designer', 'NL', 'Amsterdam', 1993, 'Dutch fashion label started by Viktor Horsting and Rolf Snoeren, known for conceptual couture. Its fragrances are made under licence by L''Oréal, and Flowerbomb remains the house''s defining scent.', 'Sweet floral gourmands in grenade bottles', 'https://www.viktor-rolf.com', 'OTB (fashion); fragrances by L''Oréal', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('2fdff95b-4f94-515d-8d45-6752537eb1a5', 'marc-jacobs', 'Marc Jacobs', 'designer', 'US', 'New York', 1984, 'American designer label founded by Marc Jacobs in New York. Its fragrances are produced under licence by Coty, and the Daisy family, with its flower-covered caps, is one of the best-known young feminine lines.', 'Light, cheerful fruity florals', 'https://www.marcjacobs.com', 'LVMH (fashion); fragrances by Coty', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('9f573424-f954-5d77-a435-4aab01792bcf', 'victorias-secret', 'Victoria''s Secret', 'mass', 'US', 'San Francisco', 1977, 'American lingerie retailer founded in San Francisco in 1977, now headquartered in Ohio. Its in-house fragrance line is sold through its own stores, and Bombshell is its long-running best seller.', 'Fruity florals and body mists sold in its own stores', 'https://www.victoriassecret.com', 'Victoria''s Secret & Co.', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('d25cb15e-7807-5cbc-a8f1-f22d29f5c8dc', 'guerlain', 'Guerlain', 'heritage', 'FR', 'Paris', 1828, 'One of the oldest perfume houses still operating, founded in Paris in 1828 by Pierre-François-Pascal Guerlain. Several generations of the family composed its classics, and the house has belonged to LVMH since the 1990s.', 'Vanilla-rich orientals and early-20th-century classics', 'https://www.guerlain.com', 'LVMH', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('1ec5b57b-bc1c-53c7-ad3a-70402b6c5413', 'creed', 'Creed', 'niche', 'FR', 'Paris', 1760, 'Creed presents itself as a family house founded in London in 1760, a heritage claim that historians have questioned. Now based in France, it was bought by Kering Beauté in 2023 and is best known for Aventus.', 'Fruity-woody masculines and luxury fresh scents', 'https://www.creedboutique.com', 'Kering Beauté', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('b9587ade-cbb2-5550-8f31-63204aff3035', 'maison-francis-kurkdjian', 'Maison Francis Kurkdjian', 'niche', 'FR', 'Paris', 2009, 'Paris house founded in 2009 by perfumer Francis Kurkdjian and businessman Marc Chaya. LVMH took a majority stake in 2017. Baccarat Rouge 540 turned it into one of the most recognised niche names of the 2020s.', 'Radiant ambery woods and clean musks', 'https://www.franciskurkdjian.com', 'LVMH', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('904e1bd9-c631-522b-a4d0-b195f8feaaf1', 'le-labo', 'Le Labo', 'niche', 'US', 'New York', 2006, 'Founded in New York in 2006 by Fabrice Penot and Edouard Roschi, Le Labo blends many of its perfumes to order in store and prints a personalised label for each bottle. Estée Lauder bought the brand in 2014.', 'Skin-close woods and musks named after a lead material', 'https://www.lelabofragrances.com', 'The Estée Lauder Companies', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('04705ae3-d73d-56c0-a99e-95f5f1e0b934', 'byredo', 'Byredo', 'niche', 'SE', 'Stockholm', 2006, 'Stockholm house founded by Ben Gorham in 2006, built around minimal design and memory-themed perfumes. Puig acquired a majority of the company in 2022.', 'Soft, airy woods and minimalist bottles', 'https://www.byredo.com', 'Puig', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('94262971-8fc6-5d8a-ab13-66dd9e4ec5d4', 'diptyque', 'Diptyque', 'niche', 'FR', 'Paris', 1961, 'Started in 1961 as a shop on Boulevard Saint-Germain by three friends working in design and painting. It sold scented candles before its first eau de toilette in 1968, and its oval labels with dancing letters are among the most recognisable in perfume.', 'Naturalistic fig, rose and woody scents; candles', 'https://www.diptyqueparis.com', 'Manzanita Capital', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('568fd41f-780b-5b8b-b063-780dc6af9ef1', 'tom-ford', 'Tom Ford', 'designer', 'US', 'New York', 2005, 'Fashion brand launched by designer Tom Ford in 2005, with a beauty line made by Estée Lauder from 2006. Its Private Blend collection, introduced in 2007, works as the brand''s niche line, and Estée Lauder acquired the whole brand in 2023.', 'Plush ambers, ouds and tobacco in Private Blend', 'https://www.tomfordbeauty.com', 'The Estée Lauder Companies', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('8f763631-4029-5efb-82eb-8a5377f26d73', 'maison-margiela', 'Maison Margiela', 'designer', 'FR', 'Paris', 1988, 'Paris fashion house founded by Belgian designer Martin Margiela in 1988 and now part of OTB. Its fragrances are made by L''Oréal; the Replica line recreates specific places and moments, each bottle labelled with a time and a location.', 'Replica: cosy, memory-themed scents', 'https://www.maisonmargiela.com', 'OTB (fashion); fragrances by L''Oréal', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('af449ff2-2289-5445-9b38-8ad776f8954d', 'parfums-de-marly', 'Parfums de Marly', 'niche', 'FR', 'Paris', 2009, 'Parfums de Marly was founded in 2009 by Julien Sprecher and takes its imagery from the horse culture of the 18th-century French court. Its fragrances lean rich and long-lasting, and several of its men''s scents have become modern niche bestsellers.', 'Big, polished ambers and spiced woods', 'https://parfums-de-marly.com', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('d7cc0c34-9924-5afe-aa0b-10e3afe19f0d', 'frederic-malle', 'Frédéric Malle', 'niche', 'FR', 'Paris', 2000, 'Editions de Parfums Frédéric Malle launched in 2000 with an unusual premise: the perfumer is credited on the bottle like an author on a book. The catalogue reads like a who''s who of modern perfumery, and the house has been part of Estée Lauder since 2014.', 'Perfumer-signed compositions', 'https://www.fredericmalle.com', 'The Estée Lauder Companies', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('01a55fb0-92dd-55af-a49a-9421cf891d10', 'serge-lutens', 'Serge Lutens', 'niche', 'FR', 'Paris', 1992, 'Serge Lutens'' perfume line grew out of his long work with Shiseido and the Salons du Palais Royal boutique in Paris, opened in 1992. Most of the catalogue was composed with perfumer Christopher Sheldrake and is known for dense, resinous, unusual ideas.', 'Dark ambers, spice and resin', 'https://www.sergelutens.com', 'Shiseido', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('1d254065-b9d9-5011-888a-329bd0a11564', 'escentric-molecules', 'Escentric Molecules', 'niche', 'DE', 'Berlin', 2006, 'Escentric Molecules was started in 2006 by perfumer Geza Schoen. Each Molecule fragrance is a single aroma chemical in alcohol, paired with an Escentric fragrance built around the same material.', 'Single-molecule fragrances', 'https://www.escentric.com', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('60cdd789-518e-512a-83e1-3b15fbe193e0', 'juliette-has-a-gun', 'Juliette Has a Gun', 'niche', 'FR', 'Paris', 2006, 'Juliette Has a Gun was founded by Romano Ricci, a member of the Nina Ricci family. The brand has a playful, slightly irreverent tone and is best known for minimal, musky scents.', 'Minimal musks and ambroxan', 'https://www.juliettehasagun.com', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('9dca2877-71fd-5ba8-b459-922bc4e70abb', 'xerjoff', 'Xerjoff', 'niche', 'IT', 'Turin', 2003, 'Xerjoff is a Turin-based luxury house founded by Sergio Momo. Its large catalogue spans several collections, and it is known for opulent bottles and rich, sweet, long-lasting compositions.', 'Opulent, sweet orientals', 'https://www.xerjoff.com', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('d451a600-ad43-5fac-8d51-21a73b63e0d4', 'kilian', 'Kilian Paris', 'niche', 'FR', 'Paris', 2007, 'Kilian was founded in 2007 by Kilian Hennessy, of the cognac family, and joined Estée Lauder in 2016. Its fragrances come in heavy refillable bottles and often play on boozy, sweet or sensual themes.', 'Boozy gourmands and lush florals', 'https://www.bykilian.com', 'The Estée Lauder Companies', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('85666cf5-a350-5def-be0c-343685c856d7', 'lattafa', 'Lattafa', 'regional', 'AE', 'Dubai', 2012, 'Lattafa is a Dubai-based perfume house making Arabian-style and Western-style fragrances at low prices. Its sweet, strong-performing scents found a big international audience online in the early 2020s.', 'Affordable gourmands and ambers', 'https://www.lattafa.com', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('8ac4ec25-b561-52eb-9fbe-7731db164532', 'armaf', 'Armaf', 'regional', 'AE', 'Dubai', 2010, 'Armaf is a fragrance brand of the Dubai-based Sterling Parfums group. It is known for inexpensive, long-lasting fragrances, several of which are often compared with famous niche scents.', 'Budget-friendly, strong performers', 'https://www.armaf.com', 'Sterling Parfums', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('7dfba177-cebf-51f0-8e8b-a0b8227257eb', 'rasasi', 'Rasasi', 'regional', 'AE', 'Dubai', 1979, 'Rasasi is a long-established Dubai perfume house making both traditional Arabian perfumery (attars, oud blends) and Western-style sprays. Its affordable sweet aquatic Hawas made it widely known outside the Gulf.', 'Oud blends and sweet aquatics', 'https://www.rasasi.com', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('83ecb717-70d9-5949-a7a7-416853693ca7', 'sol-de-janeiro', 'Sol de Janeiro', 'mass', 'US', 'New York', 2015, 'Sol de Janeiro is a body care brand inspired by Brazilian beach culture, launched in 2015 with its Brazilian Bum Bum Cream. Its fragrance mists, which share scents with the creams, became a huge category on their own.', 'Gourmand body mists', 'https://soldejaneiro.com', 'L''Occitane Group', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('4242e0b6-d872-5708-96e1-192f9aa9c364', 'bvlgari', 'Bvlgari', 'designer', 'IT', 'Rome', 1884, 'Bvlgari was founded in Rome in 1884 as a silver and jewellery shop and is now part of LVMH. Its perfumes, launched from the 1990s, include tea-themed scents and several well-regarded experimental releases.', 'Tea notes and jeweller-style bottles', 'https://www.bulgari.com', 'LVMH', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('8b2bd8f5-2ae4-5fb4-ba30-444275eb23ad', 'jo-malone', 'Jo Malone London', 'designer', 'GB', 'London', 1994, 'Jo Malone London began with a London shop opened by Jo Malone in 1994 and was bought by Estée Lauder in 1999. It is known for simple, light colognes designed to be layered.', 'Layerable colognes', 'https://www.jomalone.com', 'The Estée Lauder Companies', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false);
insert into public.perfumers (id, slug, name, country, born_year, bio, signature, wikidata_qid, data_source_id, source_url, is_demo) values
  ('e655e61c-71f5-5647-8cf5-e8c9d462ed50', 'francois-demachy', 'François Demachy', 'FR', null, 'French perfumer who spent decades at Chanel before becoming Dior''s in-house perfume creation director in 2006. He composed Sauvage and reworked many Dior classics before handing over to Francis Kurkdjian in 2021.', 'Clean, high-impact designer freshness', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('b12e6771-8a48-5946-8bc6-ced2e0cb600f', 'jacques-polge', 'Jacques Polge', 'FR', null, 'Chanel''s in-house perfumer from 1978 until 2015, when his son Olivier succeeded him. His Chanel work includes Coco, Allure, Coco Mademoiselle and Bleu de Chanel.', 'Smooth, polished florals and woods', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('5965c2e1-2a3a-5e7e-86e4-3d69a030e489', 'olivier-polge', 'Olivier Polge', 'FR', null, 'Perfumer who worked at IFF before succeeding his father Jacques as Chanel''s in-house perfumer in 2015. Before Chanel he co-created La Vie Est Belle and composed Dior Homme.', 'Iris, soft woods, quiet precision', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('0fca7eaa-6a26-5f0b-9f14-968bc1e7ee93', 'alberto-morillas', 'Alberto Morillas', 'ES', null, 'Seville-born perfumer at Firmenich, based in Geneva for most of his career. He composed Acqua di Giò pour Homme and co-created CK One, two of the defining fresh fragrances of the 1990s.', 'Musky, transparent freshness', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('17c2125d-f291-5259-a6a6-77a6e909e259', 'dominique-ropion', 'Dominique Ropion', 'FR', null, 'Long-serving perfumer at IFF known for both technically complex niche work and huge designer launches. He composed YSL Y and co-created La Vie Est Belle.', 'Dense, radiant structures', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('2bb65ba2-3005-5542-86c5-7cac5936bbb1', 'jean-claude-ellena', 'Jean-Claude Ellena', 'FR', null, 'Perfumer from Grasse who was Hermès''s first in-house perfumer, from 2004 until 2016. He is known for sparse, watercolour-like compositions such as Terre d''Hermès and the Hermès garden series.', 'Minimal, airy sketches', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('4ac1e7ae-5436-5c0b-a344-d66dd49dc849', 'aurelien-guichard', 'Aurélien Guichard', 'FR', null, 'French perfumer from a Grasse perfume family. He composed Versace Eros.', 'Bright, sweet and youthful', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('4cc151d6-d5dc-51ee-a0ae-6e873f30fe98', 'francis-kurkdjian', 'Francis Kurkdjian', 'FR', null, 'Paris perfumer who composed Le Male in the mid-1990s, co-founded Maison Francis Kurkdjian in 2009 and became Dior''s perfume creation director in 2021.', 'Glowing musks and polished ambers', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('b14dab90-e4c7-53a6-91e0-274ee7998b64', 'christophe-raynaud', 'Christophe Raynaud', 'FR', null, 'French perfumer with a long list of designer launches. He co-created Paco Rabanne 1 Million.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('917732a4-8576-538b-91bb-fdeeb5112298', 'olivier-pescheux', 'Olivier Pescheux', 'FR', null, 'French perfumer with a long career at Givaudan. He co-created Paco Rabanne 1 Million.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('5ce8cc02-ccb8-5491-be70-380fc5bd9311', 'michel-girard', 'Michel Girard', 'FR', null, 'French perfumer at Givaudan. He co-created Paco Rabanne 1 Million.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('35eaf834-7a44-5b74-95d9-33f16b145e1d', 'daniela-andrier', 'Daniela Andrier', 'DE', null, 'German-born perfumer at Givaudan who has composed most of Prada''s fragrance line since the early 2000s, including Prada L''Homme and the Infusion series.', 'Clean iris and soapy powder', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('811ad7d9-fb9c-5cc0-99cb-8f999eed1f6c', 'pierre-bourdon', 'Pierre Bourdon', 'FR', null, 'French perfumer whose best-known works include Davidoff Cool Water and Yves Saint Laurent Kouros. Cool Water helped set the template for fresh aromatic masculines in the 1990s.', 'Fresh, emphatic aromatics', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('95966aa9-7651-5358-b6ee-316bf2d1da56', 'edmond-roudnitska', 'Edmond Roudnitska', 'FR', 1905, 'One of the most influential French perfumers of the 20th century, who composed Diorissimo, Diorella and Eau Sauvage for Dior. He also wrote widely about perfume as an art form.', 'Clarity, restraint, airy florals', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('b47b3e49-2fae-5307-a11b-9e4bd37ab8ae', 'ernest-beaux', 'Ernest Beaux', 'FR', 1881, 'Moscow-born French perfumer who trained at the Rallet perfume house in Russia and composed Chanel N°5 in 1921. He became Chanel''s first in-house perfumer.', 'Aldehydic abstraction', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('cc3542c2-ead1-5681-af08-b9ec340a6811', 'nathalie-lorson', 'Nathalie Lorson', 'FR', null, 'Perfumer at Firmenich with a long list of mainstream launches. She co-created YSL Black Opium.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('41c91f0b-8ed9-5748-8d10-e07ce2d100e0', 'marie-salamagne', 'Marie Salamagne', 'FR', null, 'Perfumer at Firmenich who has worked on both designer and niche launches. She co-created YSL Black Opium.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('17dced63-6a04-5c10-9f99-b43af7388e94', 'olivier-cresp', 'Olivier Cresp', 'FR', null, 'Veteran Firmenich perfumer from a Grasse family who co-created Mugler Angel. He also co-created YSL Black Opium.', 'Bold, sweet, fruity signatures', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('9412eb99-bce3-55f0-963d-2c7ceeaf5afe', 'honorine-blanc', 'Honorine Blanc', 'FR', null, 'Perfumer at Firmenich who has worked on many designer launches. She co-created YSL Black Opium.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('d4c991ee-117c-5318-a51a-5ba11fc56b18', 'anne-flipo', 'Anne Flipo', 'FR', null, 'Perfumer at IFF known for luminous florals in both designer and niche work. She co-created La Vie Est Belle.', 'Luminous, natural-feeling florals', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('689290aa-f5f7-5e21-8f05-dc79ef3b5358', 'calice-becker', 'Calice Becker', 'FR', null, 'Perfumer credited with Dior''s J''adore (1999). Her other well-known credits include Tommy Girl.', 'Luminous, rounded white florals', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('0f73df6d-3f7c-5a29-b902-59667a501b6c', 'louise-turner', 'Louise Turner', 'GB', null, 'British perfumer credited with Carolina Herrera''s Good Girl and Maison Margiela''s Replica Lazy Sunday Morning.', 'Polished florals and soft musks', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('62756fcc-91b6-586b-91ce-c1e81a589a8a', 'carlos-benaim', 'Carlos Benaïm', 'MA', null, 'Long-serving perfumer credited on many mainstream launches, including Viktor&Rolf Flowerbomb with three co-authors.', 'Warm, generous florals', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('55c2fad2-08c4-5614-88b7-6f22f87057ff', 'domitille-bertier', 'Domitille Bertier', 'FR', null, 'French perfumer credited as one of the four co-authors of Viktor&Rolf Flowerbomb (2005).', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('bb19e15c-3d7d-5e1e-b32b-8827920a1238', 'jacques-guerlain', 'Jacques Guerlain', 'FR', 1874, 'Third-generation Guerlain perfumer and the house''s principal creator for the first half of the 20th century. His classics include Mitsouko (1919) and Shalimar (1925).', 'Vanilla, bergamot and plush powdery bases', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('26d1c370-68a8-59d0-a127-2125eef5f3a8', 'olivier-creed', 'Olivier Creed', 'FR', null, 'Long-time head of the Creed house, credited with many of its best-known scents, including Aventus (2010) with his son Erwin Creed.', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('91e49db5-8e15-50f1-a6b7-f82c5644687d', 'erwin-creed', 'Erwin Creed', 'FR', null, 'Member of the Creed family, credited alongside his father Olivier Creed on Aventus (2010).', null, null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('dcb5df8f-82ca-5bb7-bbc6-e335a3057db7', 'frank-voelkl', 'Frank Voelkl', 'DE', null, 'German-born perfumer credited with Le Labo Santal 33 (2011), one of the defining niche woods of the 2010s.', 'Dry, transparent woods', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('7d82af93-b4ae-5124-847f-6b38991081ae', 'jerome-epinette', 'Jérôme Epinette', 'FR', null, 'French perfumer widely associated with many of Byredo''s early fragrances, including Gypsy Water (2008). The house itself rarely credits perfumers.', 'Airy woods and soft incense', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('a0c808da-6744-5c1a-9a77-626319a3c436', 'olivia-giacobetti', 'Olivia Giacobetti', 'FR', null, 'French perfumer known for sheer, naturalistic compositions. She created Diptyque Philosykos (1996), a landmark fig fragrance.', 'Sheer, airy naturalism', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('8a9b1ab6-f25f-5092-a241-e0fa0030007b', 'olivier-gillotin', 'Olivier Gillotin', 'FR', null, 'French perfumer credited with Tom Ford Private Blend Tobacco Vanille (2007).', 'Rich, warm orientals', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('908ac631-69d7-5a0c-a024-569d93a82827', 'richard-herpin', 'Richard Herpin', 'FR', null, 'French perfumer credited with Tom Ford Private Blend Oud Wood (2007), one of the first Western oud fragrances to reach a mainstream audience.', 'Smooth woods', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('f29f9fd3-147c-56bc-b0b5-243b4871364d', 'alienor-massenet', 'Alienor Massenet', 'FR', null, 'French perfumer credited with Maison Margiela''s Replica Jazz Club (2013).', 'Cosy, textured warmth', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('7a0f24b2-7c9e-56da-b439-43e16067fbf8', 'hamid-merati-kashani', 'Hamid Merati-Kashani', 'FR', null, 'Perfumer credited with Layton and several other Parfums de Marly fragrances.', 'Warm, crowd-pleasing spiced woods', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('fdad0afb-e705-5f24-88d8-a32d461ccd90', 'christopher-sheldrake', 'Christopher Sheldrake', 'GB', null, 'British perfumer best known for his long collaboration with Serge Lutens, which produced Chergui and much of the house catalogue.', 'Dark, resinous, spiced ambers and woods', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('f292b153-79a6-5f19-9661-c7cb3734f268', 'geza-schoen', 'Geza Schoen', 'DE', null, 'Berlin-based perfumer who founded Escentric Molecules in 2006 around the idea of wearing a single aroma chemical.', 'Minimal, molecule-led woods', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('c290f58b-e3ea-5345-9c4d-5e8e63c47c0f', 'romano-ricci', 'Romano Ricci', 'FR', null, 'Founder of Juliette Has a Gun and a member of the family behind the Nina Ricci fashion house.', 'Playful, minimal musks and ambers', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('ee13bd26-0595-5669-8fa9-47401fc2441a', 'annick-menardo', 'Annick Ménardo', 'FR', null, 'French perfumer whose credits include Bvlgari Black and Dior Hypnotic Poison.', 'Unusual gourmand and smoky ideas', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('214b79e9-5f57-5758-a873-25ffc8022047', 'harry-fremont', 'Harry Frémont', 'US', null, 'Perfumer credited with Tom Ford Grey Vetiver among many designer fragrances.', 'Clean, polished woods and citrus', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false),
  ('8d833172-850a-5eb7-8b72-ced8695e5560', 'christine-nagel', 'Christine Nagel', 'CH', null, 'Swiss perfumer who created Wood Sage & Sea Salt for Jo Malone London and later became in-house perfumer at Hermès.', 'Textured, mineral and salty freshness', null, '925b52d1-c4ca-5b03-9d1e-6e631b61362a', null, false);
insert into public.fragrances (id, slug, name, brand_id, concentration, release_year, discontinued_year, status, marketed_for, style, summary, best_for, official_description, editorial, country, price_band, typical_price_usd, typical_size_ml, accent_hex, bottle_spec, phase_heart_min, phase_drydown_min, is_demo) values
  ('67b441bd-5946-55b3-8cb6-b873f7531077', 'dior-sauvage', 'Sauvage', '94426ffc-26b4-5ba6-89ed-da666de3cd55', 'edt', 2015, null, 'current', 'masculine', 'Fresh spicy ambroxan', 'A blast of peppery bergamot that turns into a big, clean, slightly salty ambroxan glow. Bright, loud and very easy to like.', 'Everyday wear, casual nights out', null, 'You have almost certainly smelled Sauvage on a stranger this week. Demachy pairs a sharp, peppery bergamot with a heavy dose of ambroxan, and the result is clean, bright and loud enough to fill a lift. It has been one of the best-selling men''s fragrances in the world for years, which is both its strength and its problem: it smells good and it smells everywhere.', 'FR', 'premium', 135, 100, '#3D5573', '{"body":"block","width":1.1,"height":1.4,"depth":0.6,"glass":"tinted","glassTint":"#5E7590","glassGradient":"#12161D","liquid":"#C3CEDA","fill":0.82,"cap":"cube","capMaterial":"black","capColor":"#1A202B","capWidth":1.4,"capHeight":1.25,"collar":"none","label":"printed","labelInk":"#C9CED6"}'::jsonb, 20, 150, false),
  ('03e43bb2-ea8e-5242-8d5f-3787d5612f96', 'bleu-de-chanel-edp', 'Bleu de Chanel', '3b935de0-5e9c-5c37-a5f2-d6d6ade57c8a', 'edp', 2014, null, 'current', 'masculine', 'Woody citrus incense', 'Grapefruit and a cool mint-pepper lift up front, then smooth cedar and sandalwood with a soft thread of incense. Clean, warm and quietly expensive.', 'Office days, dinners, any time', null, 'Bleu de Chanel is the safe answer to "what should I wear to the interview", and it earns that by being genuinely well made. The EDP trims the EDT''s sharper citrus edge and leans into sandalwood and a faint incense warmth. It is not daring. It is very, very good at being liked.', 'FR', 'premium', 175, 100, '#2B3A55', '{"body":"block","width":1.15,"height":1.35,"depth":0.6,"glass":"tinted","glassTint":"#1B2740","liquid":"#2A3A5A","fill":0.85,"cap":"cube","capMaterial":"black","capColor":"#151A24","capWidth":1.5,"capHeight":1,"collar":"none","label":"printed","labelInk":"#C7CBD2"}'::jsonb, 20, 180, false),
  ('c2a1b309-2cf6-5e8c-a644-55b30f12be7a', 'acqua-di-gio', 'Acqua di Giò', '531aa3f7-357c-5099-9164-8f3edaac55fc', 'edt', 1996, null, 'current', 'masculine', 'Aquatic citrus', 'Squeezed lime and bergamot over a cool, watery, slightly salty sea note, settling into soft musk and a little patchouli. Smells like a clean shirt by the sea.', 'Hot days, gym bag, office in summer', null, 'Acqua di Giò did for 1990s bathrooms what Sauvage did for the 2010s: it became the default. Morillas built it on bright citrus and a calone-style sea note that reads as clean water rather than fish market, then softened it with musk. It feels a bit dated in the opening now, but the drydown is still a pleasant, wearable skin scent.', 'IT', 'premium', 120, 100, '#6F8F95', '{"body":"flask","width":1,"height":1.15,"depth":1.4,"glass":"frosted","glassTint":"#DCE5E4","liquid":"#BCD6CF","fill":0.85,"cap":"cylinder","capMaterial":"silver","capWidth":0.85,"capHeight":0.9,"collar":"none","label":"printed","labelInk":"#3A4A4C"}'::jsonb, 15, 120, false),
  ('450ec29e-db66-5e13-a61e-8942dd8ac86b', 'ysl-y-edp', 'Y', 'aedf7762-e058-583d-b213-c57401794864', 'edp', 2018, null, 'current', 'masculine', 'Sweet fresh aromatic woods', 'Crisp apple and ginger over a sage-and-juniper heart, drying down to sweet tonka and a big dry ambery wood. Fresh on top, warm and dense underneath.', 'Evenings out, cooler months, dates', null, 'Y EDP is what happens when a fresh blue fragrance spends more time in the gym and the patisserie. The apple-ginger opening is bright and almost sparkling, but the real story is the drydown: tonka, sage and a very dry, very persistent woody amber. It is crowd-tested rather than adventurous, and it lasts.', 'FR', 'premium', 165, 100, '#4A5878', '{"body":"tall","width":1.3,"height":1.05,"depth":1,"glass":"tinted","glassTint":"#22304D","glassGradient":"#151C2E","liquid":"#3B4C6E","fill":0.85,"cap":"cube","capMaterial":"black","capColor":"#161A24","capWidth":1.1,"capHeight":0.9,"collar":"silver","label":"plate","labelColor":"#BFC3C9","labelInk":"#1D2433"}'::jsonb, 20, 150, false),
  ('65c20ca3-3513-5ba0-a424-72ba1b845a51', 'terre-d-hermes', 'Terre d''Hermès', '37c2be55-c758-592c-a46f-9daee8a86d7e', 'edt', 2006, null, 'current', 'masculine', 'Mineral citrus woods', 'Bitter orange peel and pepper over something dry and stony, like struck flint, then vetiver and cedar. Earthy, orange-tinted and quietly confident.', 'Office, autumn days, smart-casual', null, 'Terre is Ellena at his most persuasive: very few materials, each one doing a lot. The orange opening is dry and peel-bitter rather than juicy, and the flinty, peppery heart gives it the feel of sun-baked earth. It became a modern classic because it smells grown-up without smelling old.', 'FR', 'premium', 135, 100, '#A0623A', '{"body":"block","width":1.05,"height":1.3,"depth":0.7,"glass":"clear","liquid":"#C7782E","fill":0.85,"cap":"cube","capMaterial":"silver","capWidth":1.2,"capHeight":0.7,"collar":"none","label":"printed","labelInk":"#3B2A1E"}'::jsonb, 25, 180, false),
  ('1fdcba74-e517-5fc8-b913-7970d1d524a1', 'versace-eros', 'Eros', 'f65bdbf9-1992-59a4-8a31-5258a0bfeb37', 'edt', 2012, null, 'current', 'masculine', 'Sweet minty vanilla', 'Cold mint and green apple hit first, then a sweet, creamy vanilla-tonka base that hangs around all night. Loud, sugary and built for a crowd.', 'Clubs, parties, cold nights', null, 'Eros is the mint-chocolate-chip ice cream of men''s fragrance: obvious, sweet and hard to dislike once it is in front of you. The mint and apple opening is genuinely fun, and the vanilla base projects like a loudspeaker. Go easy on the trigger; two sprays is plenty.', 'IT', 'premium', 110, 100, '#3F8A86', '{"body":"block","width":1.05,"height":1.3,"depth":0.6,"glass":"tinted","glassTint":"#3E9C99","liquid":"#8CC9C2","fill":0.85,"cap":"cube","capMaterial":"resin","capColor":"#2F8C88","capWidth":1.2,"capHeight":0.85,"collar":"gold","label":"plate","labelColor":"#C8A35A","labelInk":"#3A2E14"}'::jsonb, 20, 150, false),
  ('c9e665b3-722a-5f06-9651-0b142e157be9', 'le-male', 'Le Male', 'f0054016-723d-582a-9fa2-9a72258e5fa2', 'edt', 1995, null, 'current', 'masculine', 'Lavender vanilla fougère', 'Cool mint and lavender up top, a warm hint of cinnamon and cumin, then a soft vanilla-tonka base. Barbershop meets baby powder, in a good way.', 'Cool evenings, nights out, nostalgia', null, 'Le Male took the old barbershop fougère, added a big spoonful of vanilla and a wink, and somehow made it the smell of a generation of nightclubs. Under the sweetness there is still a proper lavender-mint structure, which is why it has aged better than most of its peers. It reads warmer and softer than modern fresh masculines.', 'FR', 'premium', 125, 125, '#5A7896', '{"body":"pebble","width":0.95,"height":1.5,"depth":1,"glass":"frosted","glassTint":"#C9D8E6","liquid":"#9DBAD3","fill":0.9,"cap":"cylinder","capMaterial":"silver","capWidth":0.7,"capHeight":0.6,"collar":"none","label":"none"}'::jsonb, 20, 150, false),
  ('3cfbeea3-2cb4-58fe-befe-b233a7267bb7', 'one-million', '1 Million', 'dbba5627-c5a6-5db7-aab0-59c631745827', 'edt', 2008, null, 'current', 'masculine', 'Spicy amber leather', 'Juicy mandarin and a flash of mint, then cinnamon and rose over a sticky, sweet amber-leather base. Warm, dense and unmistakable across a room.', 'Winter nights, parties', null, '1 Million is a gold bar you can spray, and it smells about as subtle as that sounds. The cinnamon-amber-leather base is sweet and syrupy, with a slightly boozy edge that people either adore or find cloying. In cold weather and in small doses it is a lot of fun; in an office in July it is a hostile act.', 'FR', 'premium', 110, 100, '#B08A3E', '{"body":"block","width":1.15,"height":1.15,"depth":0.6,"glass":"tinted","glassTint":"#B8963E","glassGradient":"#C9A75A","liquid":"#C4983F","fill":0.85,"cap":"cube","capMaterial":"gold","capWidth":1.5,"capHeight":0.7,"collar":"none","label":"printed","labelInk":"#5A4214"}'::jsonb, 20, 140, false),
  ('f1e82d0e-2aaf-5847-8304-5af917ca9540', 'dior-homme-intense', 'Dior Homme Intense', '94426ffc-26b4-5ba6-89ed-da666de3cd55', 'edp', 2011, null, 'current', 'masculine', 'Iris and woods', 'Cool, buttery iris with a touch of pear and lavender, warming into soft cedar and vetiver. Powdery, lipstick-ish and surprisingly tender.', 'Evenings, formal wear, cold weather', null, 'Dior Homme Intense is the fragrance people mean when they say iris smells like expensive lipstick. It is cool and powdery at first, then turns surprisingly warm and close, with the pear and ambrette giving it a soft skin-like glow. It is among the most praised designer masculines for evening wear, and it projects less than its reputation suggests.', 'FR', 'premium', 155, 100, '#6E6470', '{"body":"tall","width":1.25,"height":1.05,"depth":1,"glass":"smoked","glassTint":"#4C4643","liquid":"#6E5A48","fill":0.85,"cap":"cube","capMaterial":"gunmetal","capWidth":1,"capHeight":0.9,"collar":"none","label":"printed","labelInk":"#D8D4CC"}'::jsonb, 20, 200, false),
  ('6437bd31-44df-5108-b822-78d19ae45db0', 'prada-l-homme', 'Prada L''Homme', 'ef519ad7-5a37-5f8c-9043-a756961c6df7', 'edt', 2016, null, 'current', 'masculine', 'Soapy iris and amber', 'Clean iris and neroli over a soft ambery base, with a pinch of pepper and cardamom. Smells like expensive soap on a freshly ironed shirt.', 'Office, weddings, everyday polish', null, 'L''Homme is the fragrance equivalent of a perfectly plain white shirt that turns out to be very expensive. Andrier''s iris is dry and soapy rather than lipsticky, and the amber underneath keeps it from feeling cold. It is quiet, office-proof and almost impossible to dislike, which also means it rarely starts a conversation.', 'IT', 'premium', 125, 100, '#8A8F96', '{"body":"block","width":1.05,"height":1.35,"depth":0.6,"glass":"clear","liquid":"#E7E0D2","fill":0.85,"cap":"cube","capMaterial":"black","capWidth":1.1,"capHeight":0.9,"collar":"none","label":"printed","labelInk":"#1C1A17"}'::jsonb, 15, 150, false),
  ('72168564-117b-5075-b2a3-7f025ac55772', 'cool-water', 'Cool Water', '034b778a-6efa-5ae7-89ae-cff7fda7ec61', 'edt', 1988, null, 'current', 'masculine', 'Fresh aromatic fougère', 'A cold rush of mint and lavender with a green, watery edge, drying to musky woods and a faint sweetness. The blueprint for a hundred fresh blues.', 'Hot days, gym, cheap everyday spray', null, 'Before Cool Water, "fresh" for men mostly meant citrus cologne. Bourdon pushed mint, lavender and a synthetic watery note so hard that the whole category tilted toward it for the next decade. It is cheap and a little blunt today, but there is a reason it is still on every drugstore shelf: it does exactly what the name says.', 'CH', 'accessible', 60, 125, '#3E7FA6', '{"body":"tall","width":1.2,"height":1.15,"depth":0.9,"glass":"tinted","glassTint":"#5E95BF","liquid":"#7FAED0","fill":0.85,"cap":"cylinder","capMaterial":"resin","capColor":"#2F5E86","capWidth":0.9,"capHeight":0.8,"collar":"none","label":"printed","labelInk":"#F2F4F5"}'::jsonb, 15, 120, false),
  ('be5525a1-6a03-5480-bf34-ba56efbe835c', 'nautica-voyage', 'Nautica Voyage', '08b4fcd1-387a-5dea-88ca-4e7f32783cc4', 'edt', 2006, null, 'current', 'masculine', 'Green aquatic', 'Crisp green apple and crushed leaves over a cool, watery floral heart, drying to light musk and woods. Simple, clean and absurdly cheap.', 'Summer days, gym, blind buys', null, 'Voyage is the fragrance people recommend when someone asks for "something fresh under thirty dollars", and it holds up better than the price suggests. The apple-and-leaves opening is genuinely pleasant, and the watery lotus heart keeps it light. It fades in a few hours, but at this price nobody minds respraying.', 'US', 'budget', 25, 100, '#5E8C7A', '{"body":"orb","width":1.05,"height":1,"glass":"clear","liquid":"#A7CFC4","fill":0.85,"cap":"cylinder","capMaterial":"resin","capColor":"#1F2F4A","capWidth":0.9,"capHeight":0.9,"collar":"none","label":"printed","labelInk":"#1F2F4A"}'::jsonb, 15, 100, false),
  ('f214494e-dc23-5b67-a10a-091b0e621b83', 'eau-sauvage', 'Eau Sauvage', '94426ffc-26b4-5ba6-89ed-da666de3cd55', 'edt', 1966, null, 'reformulated', 'masculine', 'Citrus aromatic chypre', 'Bright lemon and herbs with a soft, airy jasmine haze, settling on dry vetiver and a mossy hint. Crisp, cologne-like and very elegant.', 'Warm days, office, linen suits', null, 'Eau Sauvage is a lesson in how much air you can put into a bottle. Roudnitska took the traditional citrus cologne, gave it a vetiver-and-moss spine and soaked it in Hedione, which makes the whole thing feel like sunlight on a terrace. Modern versions are lighter in the moss than older bottles, but the shape of the idea is intact.', 'FR', 'premium', 125, 100, '#8C9A5E', '{"body":"apothecary","width":1.1,"height":1.15,"glass":"clear","liquid":"#E6D9A6","fill":0.85,"cap":"cylinder","capMaterial":"black","capWidth":0.95,"capHeight":0.9,"collar":"none","label":"printed","labelInk":"#1C1A17"}'::jsonb, 15, 100, false),
  ('f2a1c9a1-ad0e-5747-b419-b61fdc9eea8a', 'chanel-no-5', 'N°5', '3b935de0-5e9c-5c37-a5f2-d6d6ade57c8a', 'parfum', 1921, null, 'current', 'feminine', 'Aldehydic floral', 'A fizzy, soapy sparkle of aldehydes over rose, jasmine and ylang, settling into creamy sandalwood, vanilla and soft musk. Abstract, powdery and unmistakable.', 'Formal evenings, cold weather, classic taste', null, 'N°5 is the most famous perfume in the world, and the parfum is the closest you can get to the 1921 idea. The aldehydes give it that bright, almost waxy fizz, and the florals are blended so tightly you cannot pick out a single flower. Many people meet it in the brighter, more diffusive Eau de Parfum; the parfum is softer, rounder and sits closer to skin.', 'FR', 'luxury', 180, 15, '#C8A96A', '{"body":"block","width":0.85,"height":1,"depth":0.6,"glass":"clear","liquid":"#DDB868","fill":0.85,"cap":"faceted","capMaterial":"resin","capColor":"#ECE8DC","capWidth":1.2,"capHeight":0.8,"collar":"black","label":"paper","labelColor":"#F4F1EA","labelInk":"#141312"}'::jsonb, 25, 240, false),
  ('57d337ab-3d68-59a5-b5b6-c9c6a939a0f3', 'coco-mademoiselle', 'Coco Mademoiselle', '3b935de0-5e9c-5c37-a5f2-d6d6ade57c8a', 'edp', 2001, null, 'current', 'feminine', 'Citrus rose patchouli', 'Sparkling orange and bergamot over a fresh rose and jasmine heart, drying to clean patchouli, vetiver and soft vanilla musk. Bright, polished and long-lasting.', 'Office, daytime events, all year', null, 'Coco Mademoiselle took the patchouli chypre, scrubbed the dirt off it and added a lot of sparkle, and in doing so wrote the template for the modern "fresh oriental" feminine. The opening is all orange zest, the heart a clean rose, and the patchouli drydown is smooth enough for an office. It is everywhere for good reason, and it lasts.', 'FR', 'premium', 175, 100, '#B4848A', '{"body":"block","width":1,"height":1.3,"depth":0.6,"glass":"clear","liquid":"#E7B9A6","fill":0.85,"cap":"cube","capMaterial":"resin","capColor":"#EFE9E4","capWidth":1,"capHeight":0.85,"collar":"none","label":"printed","labelInk":"#141312"}'::jsonb, 20, 180, false),
  ('37017216-e3c9-5a14-a11b-2b05c2452785', 'black-opium', 'Black Opium', 'aedf7762-e058-583d-b213-c57401794864', 'edp', 2014, null, 'current', 'feminine', 'Coffee vanilla gourmand', 'Pear and pink pepper for a moment, then black coffee poured over sweet vanilla and white flowers. Dark, sugary and very much a night-out scent.', 'Nights out, dates, winter', null, 'Black Opium shares a name with the 1977 Opium and almost nothing else. It is a coffee-vanilla gourmand built for the club rather than the salon, and it did more than most launches to make coffee a mainstream perfume note. The opening has a pleasant bitter edge, but the long drydown is mostly sweet vanilla, so it can feel cloying in heat.', 'FR', 'premium', 155, 90, '#4A2E3A', '{"body":"pebble","width":0.95,"height":1.35,"depth":1,"glass":"tinted","glassTint":"#1B1719","glassGradient":"#2A2226","liquid":"#3A2A2E","fill":0.85,"cap":"cylinder","capMaterial":"black","capColor":"#151214","capWidth":0.85,"capHeight":0.85,"collar":"none","label":"printed","labelInk":"#D9A7B4"}'::jsonb, 15, 150, false),
  ('33125977-2cbc-5d2c-9c22-68baf45d2f1c', 'la-vie-est-belle', 'La Vie Est Belle', '145ed50c-1592-563f-810f-373d45c65e81', 'edp', 2012, null, 'current', 'feminine', 'Iris praline gourmand', 'A juicy pear and blackcurrant opening melts into sweet praline and vanilla, with powdery iris and a bit of patchouli keeping it upright. Sugary and huge.', 'Cold days, evenings, comfort wear', null, 'La Vie Est Belle is one of the defining gourmands of the 2010s and one of the best-selling feminine fragrances of its decade. The praline-vanilla sweetness is the headline, but the iris gives it a powdery, slightly cosmetic backbone that stops it from being pure candy. It is loud and long-lasting, so it suits cold air better than a crowded summer train.', 'FR', 'premium', 155, 100, '#C48A94', '{"body":"block","width":1.1,"height":1.1,"depth":0.6,"glass":"clear","liquid":"#E9BDB6","fill":0.85,"cap":"cube","capMaterial":"resin","capColor":"#ECE7E3","capWidth":1,"capHeight":0.7,"collar":"black","label":"printed","labelInk":"#141312"}'::jsonb, 15, 150, false),
  ('cbac7fea-7c27-5358-af74-1ed461b0818c', 'jadore', 'J''adore', '94426ffc-26b4-5ba6-89ed-da666de3cd55', 'edp', 1999, null, 'current', 'feminine', 'Bright white floral bouquet', 'A big, sunny bouquet of jasmine, ylang-ylang and rose with a juicy pear-and-peach glow up top, settling into soft musky flowers.', 'Daytime polish, weddings, the office', null, 'J''adore is the reference point for the modern golden floral: a smooth, airbrushed bouquet where jasmine and ylang-ylang do most of the talking and no single flower stands alone. It is polished rather than daring, which is exactly why it has sold for more than twenty-five years. The fruit up top is brief, and what lasts is a clean, musky floral hum that suits almost any daytime setting.', 'FR', 'premium', 190, 100, '#B8954E', '{"body":"apothecary","width":0.85,"height":1.35,"glass":"clear","liquid":"#D8B45E","fill":0.85,"cap":"tall","capMaterial":"gold","capWidth":0.7,"capHeight":1.2,"collar":"gold","label":"printed","labelInk":"#A88A3E"}'::jsonb, 15, 150, false),
  ('ebefe06e-51c3-5256-81e8-41fb5b4c93b1', 'angel', 'Angel', '4f5e7c17-6249-5c86-9421-15e05907d592', 'edp', 1992, null, 'current', 'feminine', 'Patchouli gourmand', 'Caramel and red fruit candy collide with a huge, earthy patchouli. Sweet and dark at once, and it lasts all day and well into the night.', 'Cold nights, when you want to be noticed', null, 'Angel is the fragrance that made sweet-and-dark a genre: a sugary praline and fairground-caramel accord pushed straight into a wall of patchouli. It is famously divisive, and the performance is enormous, so one spray is a sensible start. Thirty years on it still smells unlike almost anything else at the counter, including most of what it inspired.', 'FR', 'premium', 170, 100, '#4B5A8C', '{"body":"faceted","width":1.3,"height":0.75,"depth":0.6,"glass":"tinted","glassTint":"#3F5C9E","liquid":"#4F68B0","fill":0.8,"cap":"faceted","capMaterial":"silver","capWidth":0.6,"capHeight":0.6,"collar":"silver","label":"printed","labelInk":"#C9CED8"}'::jsonb, 20, 240, false),
  ('8b9edaf0-b59c-509d-8cbc-955faf500eb2', 'good-girl', 'Good Girl', 'f8c50fa4-85ac-59d6-9fa8-446b0751452b', 'edp', 2016, null, 'current', 'feminine', 'Tuberose and tonka gourmand', 'Almond and coffee up front, then creamy tuberose and jasmine over a warm bed of tonka and cocoa. Glossy, sweet and built for evenings.', 'Date nights, parties, cool evenings', null, 'Good Girl pairs a creamy white floral with a roasted, sweet base, and the result is louder and warmer than the tuberose suggests. The almond-coffee opening is the bit people remember, while the drydown sits closer to tonka and cocoa. It sells as much on the shoe bottle as on the scent, but the scent holds up on its own.', 'US', 'premium', 150, 80, '#2E3656', '{"body":"tapered","width":1.1,"height":1.15,"depth":0.7,"glass":"tinted","glassTint":"#1F2744","liquid":"#3A2E4C","fill":0.85,"cap":"tall","capMaterial":"gold","capWidth":0.6,"capHeight":1.3,"collar":"gold","label":"none"}'::jsonb, 15, 180, false),
  ('fecae9ab-f939-589d-a9d9-dc5cc8ac2785', 'flowerbomb', 'Flowerbomb', 'b4311656-ee28-5610-b73c-be7b93b83653', 'edp', 2005, null, 'current', 'feminine', 'Sugared floral patchouli', 'A cloud of sugary jasmine, rose and freesia over a soft patchouli base. Sweet, powdery and long lasting, with a candied edge.', 'Dates, dressing up, cooler evenings', null, 'Flowerbomb is less a bouquet than a sweetened floral haze: the flowers blur together into something sugary and powdery, held up by a soft patchouli base. It was one of the scents that set the template for the sweet floral-patchouli wave of the 2010s. Expect it to last and to leave a trail, so go lightly in small rooms.', 'NL', 'premium', 185, 100, '#B07A88', '{"body":"faceted","width":1.1,"height":1,"glass":"tinted","glassTint":"#E6C4CD","liquid":"#E2A6B6","fill":0.85,"cap":"cylinder","capMaterial":"silver","capWidth":0.6,"capHeight":0.9,"collar":"silver","label":"printed","labelInk":"#8A5866"}'::jsonb, 15, 180, false),
  ('4fcc89d4-1fa6-5627-8265-44308a5c7a50', 'daisy', 'Daisy', '2fdff95b-4f94-515d-8d45-6752537eb1a5', 'edt', 2007, null, 'current', 'feminine', 'Light fruity floral', 'Strawberry and grapefruit with a green violet-leaf snap, then soft violet and gardenia drifting into clean musk and pale woods.', 'Spring days, school, easy everyday wear', null, 'Daisy is a light, friendly fruity floral that gets out of the way, which is a lot of its appeal. The strawberry and green violet-leaf opening is the most distinctive part; the rest is soft violet and clean musk. It fades to a skin scent in a few hours, so it suits people who prefer a gentle presence.', 'US', 'premium', 135, 100, '#B9A85E', '{"body":"block","width":1,"height":1,"glass":"clear","liquid":"#E6DC9E","fill":0.85,"cap":"dome","capMaterial":"white","capColor":"#F1EEE4","capWidth":1.4,"capHeight":1.1,"collar":"gold","label":"printed","labelInk":"#2A2A2A"}'::jsonb, 10, 90, false),
  ('8ad336af-2db8-50d9-a5ca-1173b78b1d0d', 'bombshell', 'Bombshell', '9f573424-f954-5d77-a435-4aab01792bcf', 'edp', 2010, null, 'current', 'feminine', 'Juicy fruity floral', 'Bright passion fruit and tropical juice over a soft peony heart, fading to a light, sweet musk. Easy, cheerful and very recognisable.', 'Warm days, casual plans, going out', null, 'Bombshell is a straightforward fruity floral: passion fruit and a general tropical juiciness up front, a soft peony middle, then a light musky sweetness. It is one of the best-selling fragrances sold through a single retailer, and the familiarity is part of the point. Longevity is moderate for an EDP.', 'US', 'accessible', 98, 100, '#B66E86', '{"body":"tall","width":1,"height":1.1,"depth":0.7,"glass":"clear","liquid":"#E7A9BC","fill":0.85,"cap":"cylinder","capMaterial":"silver","capWidth":0.8,"capHeight":0.8,"collar":"black","label":"printed","labelInk":"#2A2224"}'::jsonb, 10, 120, false),
  ('64fe90c7-af16-51ea-b651-2ddcec3c9321', 'mitsouko', 'Mitsouko', 'd25cb15e-7807-5cbc-a8f1-f22d29f5c8dc', 'edp', 1919, null, 'reformulated', 'feminine', 'Fruity mossy chypre', 'Bergamot and a soft, velvety peach over a dry, mossy, slightly spicy base. Grown-up, bittersweet and nothing like a modern fruity floral.', 'Autumn days, rain, dressed-up occasions', null, 'Mitsouko is one of the founding chypres: citrus over a damp, mossy base, with a famously soft peach note that gives it warmth and a faint melancholy. Today''s version has had to work around restrictions on oakmoss, so it reads lighter and less inky than vintage descriptions suggest. It still rewards patience, since the drydown is where it makes sense.', 'FR', 'premium', 160, 75, '#8A7044', '{"body":"apothecary","width":1.1,"height":0.95,"glass":"clear","liquid":"#B9884A","fill":0.85,"cap":"pebble","capMaterial":"resin","capColor":"#E7E0CF","capWidth":1.1,"capHeight":1.2,"collar":"gold","label":"paper","labelColor":"#EDE3CD","labelInk":"#5E4429"}'::jsonb, 20, 180, false),
  ('b2b219a2-d22b-51e9-b818-1f1e13af6600', 'shalimar', 'Shalimar', 'd25cb15e-7807-5cbc-a8f1-f22d29f5c8dc', 'edp', 1925, null, 'current', 'feminine', 'Vanilla amber classic', 'A blast of bergamot over smoky vanilla, soft iris and resinous amber. Powdery, a little leathery, and warm for hours.', 'Winter evenings, formal nights', null, 'Shalimar is the template for the vanilla amber: a sharp bergamot opening laid over vanilla with a smoky, slightly leathery undertone. The contrast between that bright top and the dense, powdery base is the whole trick, and it still works. It is warm and fairly loud, so it belongs to cold weather and evenings.', 'FR', 'premium', 170, 90, '#3E5480', '{"body":"apothecary","width":1.3,"height":0.85,"glass":"clear","liquid":"#C59A4E","fill":0.85,"cap":"disc","capMaterial":"resin","capColor":"#2F4D8A","capWidth":1.4,"capHeight":1.3,"collar":"silver","label":"printed","labelInk":"#B8BFC9"}'::jsonb, 15, 180, false),
  ('75c0a358-2a03-51ff-a32f-cb697d1939f7', 'aventus', 'Aventus', '1ec5b57b-bc1c-53c7-ad3a-70402b6c5413', 'edp', 2010, null, 'current', 'masculine', 'Fruity smoky chypre', 'Juicy pineapple, blackcurrant and bergamot over a dry, smoky birch heart, settling into clean musk and soft moss. Bright, confident, versatile.', 'Spring and summer days, work, dates', null, 'Aventus took the old fruity chypre idea and gave it a smoky birch spine and a clean musky base, and it became the most talked-about men''s niche fragrance of the 2010s. Batches are often said to vary, mostly in how much smoke comes through. The pineapple opening is the hook; the clean, slightly mossy drydown is what keeps people wearing it.', 'FR', 'luxury', 495, 100, '#5C5A4A', '{"body":"tall","width":0.95,"height":1.2,"depth":0.8,"glass":"smoked","glassTint":"#232323","liquid":"#C9C1A0","fill":0.85,"cap":"cylinder","capMaterial":"silver","capWidth":1.1,"capHeight":1.1,"collar":"silver","label":"printed","labelInk":"#C7C9CC"}'::jsonb, 15, 150, false),
  ('c48ceade-7daa-5876-864f-822e7feec28b', 'baccarat-rouge-540', 'Baccarat Rouge 540', 'b9587ade-cbb2-5550-8f31-63204aff3035', 'edp', 2015, null, 'current', 'shared', 'Airy amber woods', 'Saffron and a burnt-sugar sweetness over a glowing, mineral amber and dry cedar. Light in texture, huge in reach, and very long lasting.', 'Evenings out, cool weather, special plans', null, 'Baccarat Rouge 540 smells sweet without being heavy: saffron and a caramelised, almost burnt-sugar effect sit on top of a bright, mineral amber woods base. Its reach is enormous, and it became one of the most recognised scents of the 2020s, which means plenty of people will know what you are wearing. Some noses find it sharp or metallic rather than warm.', 'FR', 'luxury', 335, 70, '#A8634F', '{"body":"block","width":0.9,"height":1.1,"glass":"clear","liquid":"#E6B9A0","fill":0.85,"cap":"cube","capMaterial":"gold","capWidth":0.9,"capHeight":0.8,"collar":"gold","label":"printed","labelInk":"#3B2C22"}'::jsonb, 10, 120, false),
  ('1f15d7e9-9ec3-5858-9262-fd6ee4d5d2d0', 'santal-33', 'Santal 33', '904e1bd9-c631-522b-a4d0-b195f8feaaf1', 'edp', 2011, null, 'current', 'shared', 'Dry leathery sandalwood', 'Dry sandalwood and cedar with a pinch of cardamom and a worn-leather edge. Creamy, woody and a little sour, it reads like warm skin.', 'Everyday wear in cool, mild weather', null, 'Santal 33 is the sandalwood that defined a decade of niche: a dry, slightly sour, leathery wood with a cardamom lift, far from the milky sandalwood of older perfumes. It became so common in certain cities that it now reads as a social signal as much as a scent. On skin it sits close after the first hour and lasts well.', 'US', 'luxury', 330, 100, '#8E7356', '{"body":"cylinder","width":0.9,"height":1.1,"glass":"clear","liquid":"#E8DCC0","fill":0.85,"cap":"cylinder","capMaterial":"black","capWidth":1,"capHeight":0.9,"collar":"black","label":"paper","labelColor":"#F1EDE4","labelInk":"#222222"}'::jsonb, 10, 120, false),
  ('38b37b9f-c77a-5a0d-8eb8-7a680d032983', 'gypsy-water', 'Gypsy Water', '04705ae3-d73d-56c0-a99e-95f5f1e0b934', 'edp', 2008, null, 'current', 'shared', 'Soft woody aromatic', 'Bergamot, juniper and pepper over pine needles and a wisp of incense, drying down to soft vanilla and sandalwood. Calm, clean and outdoorsy.', 'Relaxed days, spring and autumn walks', null, 'Gypsy Water is a quiet, soft-focus woody scent: citrus and juniper up top, then pine and a little incense, ending in a gentle vanilla-sandalwood base. It is easy to wear and rarely offends anyone. The trade-off is modest staying power for the price, so expect to reapply.', 'SE', 'luxury', 285, 100, '#7C8466', '{"body":"cylinder","width":1,"height":1.05,"glass":"clear","liquid":"#EFE7D6","fill":0.85,"cap":"cylinder","capMaterial":"black","capWidth":1.15,"capHeight":1.1,"collar":"none","label":"paper","labelColor":"#F4F2EC","labelInk":"#1E1E1E"}'::jsonb, 10, 120, false),
  ('01b40e32-366e-50a8-acd4-441037fb29dc', 'philosykos', 'Philosykos', '94262971-8fc6-5d8a-ab13-66dd9e4ec5d4', 'edt', 1996, null, 'current', 'shared', 'Green milky fig', 'Crushed fig leaves, green and sappy, with the milky sweetness of the fruit and a dry cedar base. Like standing in the shade of a fig tree.', 'Hot days, holidays, easy daytime wear', null, 'Philosykos treats fig as a whole tree rather than a fruit: bitter green leaves, a little milky sap, then dry wood. It is sheer and naturalistic, which makes it lovely in heat and a bit faint everywhere else. It has been widely imitated, but the balance of green and creamy here is still hard to beat.', 'FR', 'premium', 175, 100, '#6F7F55', '{"body":"flask","width":0.9,"height":1.1,"depth":0.6,"glass":"clear","liquid":"#E3E2C8","fill":0.85,"cap":"cylinder","capMaterial":"white","capWidth":0.8,"capHeight":0.8,"collar":"none","label":"paper","labelColor":"#F3F1EA","labelInk":"#151515"}'::jsonb, 10, 90, false),
  ('9be8a2f0-d295-5aeb-971c-6f99cc5e0de6', 'tobacco-vanille', 'Tobacco Vanille', '568fd41f-780b-5b8b-b063-780dc6af9ef1', 'edp', 2007, null, 'current', 'shared', 'Sweet tobacco vanilla', 'Honeyed pipe tobacco and spice melt into thick vanilla, tonka, cocoa and dried fruit. Rich, boozy-sweet and very long lasting.', 'Cold nights, winter evenings out', null, 'Tobacco Vanille is about as straightforward as luxury perfume gets: sweet, honeyed tobacco leaf and a lot of vanilla, with cocoa and dried fruit thickening the middle. It is warm, loud and lasts all evening. In cold weather it is comforting; in heat it can feel like wearing a dessert trolley.', 'US', 'luxury', 295, 50, '#7A5034', '{"body":"block","width":0.9,"height":1.1,"glass":"smoked","glassTint":"#3A2418","liquid":"#6B3F22","fill":0.85,"cap":"cube","capMaterial":"resin","capColor":"#2C1B12","capWidth":0.9,"capHeight":0.8,"collar":"gold","label":"plate","labelColor":"#B6965A","labelInk":"#2C1B12"}'::jsonb, 15, 240, false),
  ('0ed90f43-0f7d-5d78-98a9-082e2bcfaa43', 'oud-wood', 'Oud Wood', '568fd41f-780b-5b8b-b063-780dc6af9ef1', 'edp', 2007, null, 'current', 'shared', 'Smooth spiced oud', 'Cardamom and zesty pepper over a smooth, polished oud with sandalwood and vetiver, softening into warm tonka and amber. Woody, never funky.', 'Office, dinners, autumn and winter', null, 'Oud Wood introduced a lot of Western wearers to oud by leaving out the barnyard: what you get is a smooth, dry wood with cardamom and pepper on top and a soft amber base. It is quiet and polished, closer to a well-cut jacket than a statement. Projection is moderate, which suits offices and dinners.', 'US', 'luxury', 295, 50, '#6A5240', '{"body":"block","width":0.9,"height":1.1,"glass":"smoked","glassTint":"#33261D","liquid":"#7A5332","fill":0.85,"cap":"cube","capMaterial":"resin","capColor":"#221811","capWidth":0.9,"capHeight":0.8,"collar":"gold","label":"plate","labelColor":"#B6965A","labelInk":"#221811"}'::jsonb, 10, 120, false),
  ('19cf2561-587d-5c34-bec6-8851996fa008', 'jazz-club', 'Replica Jazz Club', '8f763631-4029-5efb-82eb-8a5377f26d73', 'edt', 2013, null, 'current', 'masculine', 'Boozy tobacco vanilla', 'Pink pepper and lemon give way to sweet rum and tobacco leaf, settling into a soft vanilla and styrax warmth. Cosy, boozy and mellow.', 'Evenings, bars, cold-weather dates', null, 'Jazz Club takes the rum-and-tobacco idea and keeps it light enough for everyday evenings: a spritz of pepper and citrus, then sweet boozy tobacco and a soft vanilla finish. It is friendlier and less dense than the luxury tobacco scents it gets compared with. Longevity is decent for an EDT, though it stays fairly close after a couple of hours.', 'FR', 'premium', 165, 100, '#8A6038', '{"body":"flask","width":1,"height":1.05,"depth":0.7,"glass":"clear","liquid":"#C58A45","fill":0.85,"cap":"cylinder","capMaterial":"black","capWidth":0.8,"capHeight":0.8,"collar":"none","label":"paper","labelColor":"#F2F0EA","labelInk":"#2A2A2A"}'::jsonb, 10, 120, false),
  ('59d508e4-3246-5965-bdae-98a8c3b53100', 'lazy-sunday-morning', 'Replica Lazy Sunday Morning', '8f763631-4029-5efb-82eb-8a5377f26d73', 'edt', 2013, null, 'current', 'shared', 'Clean laundry musk', 'Aldehydes and a touch of pear, then lily of the valley and iris over soft, clean musk. Smells like fresh sheets and warm skin.', 'Work, weekends, anyone who wants clean', null, 'Lazy Sunday Morning is a clean-laundry musk done with a light touch: a soapy, aldehydic opening, a soft floral middle, then musk that sits close to the skin. It is one of the easiest fragrances to wear around other people. If you want presence, look elsewhere; this one is for you and whoever leans in.', 'FR', 'premium', 165, 100, '#9C9A8C', '{"body":"flask","width":1,"height":1.05,"depth":0.7,"glass":"clear","liquid":"#EFE9DA","fill":0.85,"cap":"cylinder","capMaterial":"black","capWidth":0.8,"capHeight":0.8,"collar":"none","label":"paper","labelColor":"#F2F0EA","labelInk":"#2A2A2A"}'::jsonb, 10, 90, false),
  ('f012c6f7-f13d-501f-9fe6-8cc836603c42', 'layton', 'Layton', 'af449ff2-2289-5445-9b38-8ad776f8954d', 'edp', 2016, null, 'current', 'masculine', 'Spiced vanilla apple', 'Crisp apple and lavender up top, then a warm cardamom and vanilla middle that settles into soft, peppery woods.', 'Cool evenings, dates, crowd-pleasing wear', null, 'Layton is the Parfums de Marly scent most people try first, and it is easy to see why: apple and lavender make it bright, cardamom and vanilla make it warm, and the woods stop it going sugary. It is loud for the first few hours. If you like the idea of a fougère but find the old barbershop ones too dry, this is the friendlier version.', 'FR', 'luxury', 350, 125, '#8A6E4B', '{"body":"block","width":1,"height":1.15,"depth":0.85,"glass":"clear","liquid":"#E8DDB5","fill":0.85,"cap":"cube","capMaterial":"black","capWidth":0.9,"capHeight":0.9,"collar":"gold","label":"plate","labelColor":"#B8975A","labelInk":"#2A2A2A"}'::jsonb, 20, 150, false),
  ('f1666174-e46d-533d-9b9d-6124345afee2', 'portrait-of-a-lady', 'Portrait of a Lady', 'd7cc0c34-9924-5afe-aa0b-10e3afe19f0d', 'edp', 2010, null, 'current', 'feminine', 'Dark rose and patchouli', 'A huge, dark rose with berries and clove, set on patchouli and smoky incense. Wine-red at first, drying to resin and soft sandalwood.', 'Winter evenings, nights you want to be noticed', null, 'Dominique Ropion built Portrait of a Lady around an unusually large dose of rose and an equally serious amount of patchouli, and it shows. The opening is jammy and spiced, the heart is all rose, and the base turns smoky and resinous for hours. It is marketed to women but plenty of men wear it, and one spray is often enough.', 'FR', 'luxury', 455, 100, '#7A3B3F', '{"body":"tall","width":0.9,"height":1.15,"depth":0.85,"glass":"clear","liquid":"#8C4A32","fill":0.85,"cap":"cube","capMaterial":"black","capWidth":0.95,"capHeight":1,"collar":"none","label":"paper","labelColor":"#F3EEE3","labelInk":"#A8402F"}'::jsonb, 15, 120, false),
  ('35a5f5d7-0be8-5e05-98d1-c6103c3f4dd8', 'chergui', 'Chergui', '01a55fb0-92dd-55af-a49a-9421cf891d10', 'edp', 2001, null, 'current', 'shared', 'Honeyed tobacco and hay', 'Sweet tobacco leaf and honey with dry hay and a thread of incense, drying down to soft, powdery musk and sandalwood.', 'Cold days, slow weekends, reading by a lamp', null, 'Named after a hot desert wind, Chergui is one of the Serge Lutens scents that wins over people who usually find the house too strange. The tobacco here is the cured-leaf, slightly sweet kind rather than smoke, and honey and hay give it a golden, sunny feel. Over the evening it softens into a powdery, gently resinous skin scent that lasts much longer than you expect.', 'FR', 'premium', 175, 50, '#9A6A35', '{"body":"tall","width":0.85,"height":1.1,"depth":0.7,"glass":"clear","liquid":"#B5772E","fill":0.85,"cap":"cube","capMaterial":"black","capWidth":0.9,"capHeight":0.8,"collar":"none","label":"printed","labelInk":"#1A1A1A"}'::jsonb, 20, 180, false),
  ('0c3dbc70-6685-587b-b4df-8a4f9f9137a3', 'un-jardin-sur-le-nil', 'Un Jardin sur le Nil', '37c2be55-c758-592c-a46f-9daee8a86d7e', 'edt', 2005, null, 'current', 'shared', 'Green mango and citrus', 'Tart green mango and grapefruit over a watery lotus and soft woods. Juicy, green and quiet, with a faint incense-like dryness at the end.', 'Hot days, the office, easy everyday wear', null, 'Jean-Claude Ellena made this one after a trip to Aswan, and it is a clear example of his light-handed style: a few materials and lots of air. The green mango is sour and leafy rather than tropical, which keeps it from feeling like a fruit cocktail. It doesn''t project much and fades to a woody whisper within a few hours, which is either the charm or the problem depending on what you want.', 'FR', 'premium', 165, 100, '#7E9A6E', '{"body":"flask","width":1,"height":1,"depth":0.8,"glass":"tinted","glassTint":"#C9D9B5","liquid":"#D7E3B8","fill":0.85,"cap":"pebble","capMaterial":"resin","capColor":"#7E9A6E","collar":"none","label":"printed","labelInk":"#3A4A33"}'::jsonb, 15, 90, false),
  ('353750cb-d63c-55a7-82c4-f9400136b2da', 'molecule-01', 'Molecule 01', '1d254065-b9d9-5011-888a-329bd0a11564', 'edt', 2006, null, 'current', 'shared', 'Single-molecule woods', 'Pure Iso E Super: a soft, velvety cedar-like woodiness with a faint peppery glow. Some barely smell it on themselves while others notice it all day.', 'Every day, layering, people who dislike perfume', null, 'Molecule 01 is one aroma chemical in alcohol, nothing more. Iso E Super is usually a supporting player in hundreds of fragrances, and on its own it smells of warm pencil shavings, dry cedar and clean skin. Because noses tire of it quickly, many wearers lose track of it within minutes while people around them keep noticing it.', 'DE', 'premium', 160, 100, '#8C8577', '{"body":"cylinder","width":0.8,"height":1.2,"glass":"clear","liquid":"#F1EEE4","fill":0.85,"cap":"cylinder","capMaterial":"black","capWidth":1,"capHeight":0.9,"collar":"none","label":"printed","labelInk":"#1E1E1E"}'::jsonb, 10, 60, false),
  ('124e3c86-834c-5b24-8561-6295ffd8169b', 'not-a-perfume', 'Not a Perfume', '60cdd789-518e-512a-83e1-3b15fbe193e0', 'edp', 2010, null, 'current', 'shared', 'Single-molecule ambroxan', 'Just ambroxan: a clean, faintly salty, skin-like warmth with a woody hum. Quiet up close, but it drifts out around you for hours.', 'Daily wear, sensitive noses, layering', null, 'Romano Ricci built Not a Perfume around a single material, Cetalox (a brand of ambroxan), and the house markets it as free of the common listed allergens, which is why it gets recommended to people who react to most fragrance. It smells like warm, clean skin with a mineral, woody edge. Like Molecule 01, it is easy to stop noticing on yourself.', 'FR', 'premium', 140, 100, '#A69C8A', '{"body":"block","width":0.9,"height":1.1,"depth":0.8,"glass":"clear","liquid":"#F3F0E6","fill":0.85,"cap":"faceted","capMaterial":"silver","capWidth":0.8,"capHeight":1.2,"collar":"silver","label":"printed","labelInk":"#1A1A1A"}'::jsonb, 10, 60, false),
  ('5423ce57-36cd-5b93-9f81-82cd94a38108', 'naxos', 'Naxos', '9dca2877-71fd-5ba8-b459-922bc4e70abb', 'edp', 2015, null, 'current', 'shared', 'Honey tobacco lavender', 'Bright lavender and citrus over a thick honey and cinnamon heart, settling into sweet tobacco and tonka. Rich, golden and very long-lasting.', 'Autumn and winter evenings, special nights', null, 'Naxos takes the lavender of a classic fougère and pours honey over it. The first half hour is aromatic and almost bright, then cinnamon, honey and tobacco take over and stay for most of the day. It is sweet but not sticky, and it is usually the first Xerjoff people get recommended.', 'IT', 'luxury', 295, 100, '#B07D3A', '{"body":"cylinder","width":1,"height":1.05,"glass":"clear","liquid":"#C98F3A","fill":0.85,"cap":"disc","capMaterial":"gold","capWidth":1.2,"capHeight":0.8,"collar":"gold","label":"plate","labelColor":"#C2A15B","labelInk":"#3A2A12"}'::jsonb, 25, 150, false),
  ('916b23d2-5590-528e-820b-895c1ab89b43', 'love-dont-be-shy', 'Love, Don''t Be Shy', 'd451a600-ad43-5fac-8d51-21a73b63e0d4', 'edp', 2007, null, 'current', 'shared', 'Orange blossom marshmallow', 'Orange blossom and neroli whipped into a soft marshmallow and vanilla base. Sweet and fluffy, with a bit of musky warmth underneath.', 'Dates, cosy evenings, sweet-floral fans', null, 'Love, Don''t Be Shy was one of the first Kilian launches, built by Calice Becker around orange blossom and a marshmallow accord. It is openly sugary, but the neroli and a musky, slightly animal base keep it from smelling like a sweet shop. Expect a sweet trail that lasts all evening.', 'FR', 'luxury', 295, 50, '#C98E6B', '{"body":"block","width":0.95,"height":1.05,"depth":0.8,"glass":"frosted","glassTint":"#EFE6DA","liquid":"#F1D9B8","fill":0.85,"cap":"cube","capMaterial":"silver","capWidth":1,"capHeight":0.8,"collar":"silver","label":"plate","labelColor":"#C9C9C9","labelInk":"#2A2A2A"}'::jsonb, 15, 150, false),
  ('6f07c2d9-74ef-52ce-9278-54ffa3319571', 'khamrah', 'Khamrah', '85666cf5-a350-5def-be0c-343685c856d7', 'edp', 2022, null, 'current', 'shared', 'Boozy date and spice gourmand', 'Cinnamon and nutmeg over sticky dates and praline, sinking into a dense vanilla, tonka and resin base. Sweet, boozy and very warm.', 'Cold nights, sweet-scent lovers, small budgets', null, 'Khamrah became one of the breakout budget fragrances of the early 2020s, and it is often compared with Kilian''s Angels'' Share. The opening is a warm spice-cabinet blast, the heart is dates and praline, and the base is a thick vanilla and benzoin that lasts well into the next day. It is easy to overspray: two sprays is plenty.', 'AE', 'budget', 40, 100, '#7A4A2A', '{"body":"block","width":1,"height":1.1,"depth":0.8,"glass":"smoked","glassTint":"#4A2A1A","liquid":"#7A3E1E","fill":0.85,"cap":"faceted","capMaterial":"gold","capWidth":1,"capHeight":1.1,"collar":"gold","label":"printed","labelInk":"#C9A55A"}'::jsonb, 20, 150, false),
  ('eac4a0d6-6b84-5346-9708-cb2da5961167', 'club-de-nuit-intense-man', 'Club de Nuit Intense Man', '8ac4ec25-b561-52eb-9fbe-7731db164532', 'edt', 2015, null, 'current', 'masculine', 'Smoky fruity chypre', 'A sharp, fizzy lemon and pineapple opening with smoky birch underneath, drying to musk and a dry, ambery woodiness.', 'Nights out, cooler days, budget signature', null, 'Club de Nuit Intense Man is the fragrance that made Armaf famous, mostly because it is often compared with Creed Aventus at a small fraction of the price. The opening is loud, sharp lemon with a smoky edge, which some people find harsh for the first fifteen minutes. Once it settles, the smoky pineapple and musk are well made and very long-lasting.', 'AE', 'budget', 40, 105, '#4A5058', '{"body":"tall","width":0.9,"height":1.2,"depth":0.8,"glass":"smoked","glassTint":"#141414","liquid":"#2A2A2A","fill":0.85,"cap":"cylinder","capMaterial":"silver","capWidth":0.9,"capHeight":1.2,"collar":"silver","label":"printed","labelInk":"#C8C8C8"}'::jsonb, 20, 120, false),
  ('e25dd2d2-d33e-57f4-aba8-aed582c8d94c', 'hawas', 'Hawas for Him', '7dfba177-cebf-51f0-8e8b-a0b8227257eb', 'edp', 2015, null, 'current', 'masculine', 'Sweet fruity aquatic', 'Juicy apple and plum over a cool aquatic note with cinnamon and cardamom, drying down to a sweet, ambery musk.', 'Summer nights, humid weather, casual outings', null, 'Hawas is a sweet aquatic, which sounds contradictory until you smell it: cool marine notes and apple up front, a candied plum and spice heart, and a long, sweet, musky trail. It projects strongly for the money and gets worn a lot in hot climates at night. The sweetness is heavier than in most aquatics, so it is not one for people who want crisp and dry.', 'AE', 'budget', 50, 100, '#3A6A8C', '{"body":"pebble","width":1.05,"height":1,"depth":0.8,"glass":"tinted","glassTint":"#2E5C8A","glassGradient":"#1A2E4A","liquid":"#4A7FB0","fill":0.85,"cap":"dome","capMaterial":"silver","capWidth":0.9,"capHeight":0.9,"collar":"silver","label":"printed","labelInk":"#E3E6EA"}'::jsonb, 15, 120, false),
  ('90d110b3-9c57-5999-ae1b-d3920b55b066', 'cheirosa-62', 'Cheirosa ''62', '83ecb717-70d9-5949-a7a7-416853693ca7', 'body_mist', 2018, null, 'current', 'unspecified', 'Salted caramel pistachio', 'Toasted pistachio and almond over salted caramel and vanilla, with a soft floral heart. The scent of the brand''s best-known body cream, as a light mist.', 'Warm days, after the shower, layering', null, 'Cheirosa ''62 is the scent of Sol de Janeiro''s Brazilian Bum Bum Cream, and this mist is the cheapest way to wear it head to toe. It smells of salted caramel and pistachio more than any particular flower, warm and beachy rather than dessert-heavy. As a body mist it fades within a couple of hours, so people reapply or layer it over the cream.', 'US', 'budget', 38, 240, '#D9967A', '{"body":"tall","width":0.9,"height":1.35,"depth":0.8,"glass":"tinted","glassTint":"#E8A3A0","glassGradient":"#E9B98A","liquid":"#F2C9A8","fill":0.85,"cap":"cylinder","capMaterial":"white","capWidth":0.9,"capHeight":1,"collar":"none","label":"printed","labelInk":"#9C3B5A"}'::jsonb, 10, 60, false),
  ('410f035c-dede-5ed9-89a2-44bd0d617f25', 'bvlgari-black', 'Black', '4242e0b6-d872-5708-96e1-192f9aa9c364', 'edt', 1998, null, 'discontinued', 'shared', 'Smoky tea, rubber and vanilla', 'Smoky black tea and a rubbery, tyre-like note over soft vanilla and amber. Odd on paper, oddly comforting on skin, with a gentle musky finish.', 'Cool weather, city days, fans of the unusual', null, 'Annick Ménardo''s Black was a strange idea for a jeweller in 1998: a fragrance about rubber and smoked tea, in a bottle wrapped like a tyre. It works because the vanilla and amber underneath are soft and warm, so the rubber reads as intriguing rather than industrial. It has become hard to find at regular retailers, which has only added to its reputation.', 'IT', 'accessible', 60, 75, '#3E3B38', '{"body":"cylinder","width":1.4,"height":0.7,"glass":"smoked","glassTint":"#1A1A1A","liquid":"#C9B79A","fill":0.85,"cap":"disc","capMaterial":"black","capWidth":1.1,"capHeight":0.6,"collar":"none","label":"printed","labelInk":"#B8B8B8"}'::jsonb, 15, 120, false),
  ('2e3cfee1-9758-54a2-9653-6147449d92bd', 'grey-vetiver', 'Grey Vetiver', '568fd41f-780b-5b8b-b063-780dc6af9ef1', 'edp', 2009, null, 'current', 'masculine', 'Clean citrus vetiver', 'Grapefruit and sage over clean, slightly smoky vetiver, with a hint of iris and spice. Crisp, grey and polished, like a freshly pressed shirt.', 'Office, warm days, smart-casual wear', null, 'Grey Vetiver is Tom Ford''s take on the clean, well-tailored vetiver: citrus and sage up top, a dry iris and spice middle, and a smooth woody base that stays polite. It is less earthy than the classic vetivers and less sweet than most modern woods. A reliable office scent that still feels expensive.', 'US', 'premium', 200, 100, '#7D8077', '{"body":"block","width":1,"height":1.1,"depth":0.7,"glass":"smoked","glassTint":"#6E6E6E","liquid":"#D9CDB0","fill":0.85,"cap":"cube","capMaterial":"silver","capWidth":1,"capHeight":0.8,"collar":"silver","label":"plate","labelColor":"#B9B9B9","labelInk":"#2A2A2A"}'::jsonb, 15, 120, false),
  ('7f9268d8-5974-5c4e-a155-51b9c20319e5', 'wood-sage-sea-salt', 'Wood Sage & Sea Salt', '8b2bd8f5-2ae4-5fb4-ba30-444275eb23ad', 'cologne', 2014, null, 'current', 'shared', 'Salty woody aromatic', 'Sea salt and sage over a dry, mineral woodiness, with a soft musky ambrette glow. Like a windy beach walk: light and a little savoury.', 'Spring and summer days, weekends, the office', null, 'Wood Sage & Sea Salt is one of Jo Malone London''s best-known modern colognes. Christine Nagel built it from just a few ideas: ambrette for a soft musky warmth, a sea-salt accord and herbal sage. It is airy and fairly short-lived, which suits its laid-back mood but means reapplying by mid-afternoon.', 'GB', 'premium', 170, 100, '#8A9A94', '{"body":"tall","width":1,"height":1,"depth":0.95,"glass":"clear","liquid":"#EDE8D8","fill":0.85,"cap":"cube","capMaterial":"black","capWidth":1,"capHeight":0.7,"collar":"none","label":"paper","labelColor":"#F2EEE4","labelInk":"#1A1A1A"}'::jsonb, 10, 60, false),
  ('0d0e6028-198b-5de3-ab2b-4fda9e56e5a9', 'paradigme', 'Paradigme', 'ef519ad7-5a37-5f8c-9043-a756961c6df7', 'edp', 2025, null, 'current', 'masculine', 'Woody amber', 'Bright bergamot and rosy geranium over a warm benzoin and amber base. Clean and modern at first, softer and more resinous as it wears.', 'Everyday wear, evenings, cooler months', null, 'Paradigme is Prada''s 2025 men''s launch. Built around bergamot and geranium over a resinous benzoin and amber base, it sits in the polished, easy-to-wear woody-amber lane that most big launches aim for. It is too new for a settled reputation, so treat the community figures here as a placeholder.', 'IT', 'premium', 160, 100, '#6E6658', '{"body":"block","width":0.95,"height":1.1,"depth":0.7,"glass":"clear","liquid":"#E8D7B0","fill":0.85,"cap":"cube","capMaterial":"black","capWidth":0.9,"capHeight":0.8,"collar":"black","label":"printed","labelInk":"#1A1A1A"}'::jsonb, 20, 120, false);
