  ('2c62cefd-86a3-5554-98ee-46852b1aedb2', '65c20ca3-3513-5ba0-a424-72ba1b845a51', '510aac43-1171-575b-af97-efc0035a422e', 'notes', '{"top":["sweet-orange","grapefruit"],"heart":["black-pepper","geranium","mineral"],"base":["vetiver","cedarwood","patchouli","benzoin"]}'::jsonb, null, 'facts', '2026-10-03T00:00:00Z', null, 0.55, 'accepted', 'House and retailer pages were blocked by the research network policy; Hermès describes orange, grapefruit, flint (mapped to our mineral descriptor), pepper, pelargonium (mapped to geranium), vetiver, cedar, patchouli and benzoin. Phase placement is ours.'),
