insert into public.profiles (id, handle, display_name, bio, location, experience_level, is_private, role, avatar_hue, is_demo, created_at) values
  ('671152e1-7913-561d-bf2f-a2bac69ed43a', 'demo', 'Demo Account', 'The account you are poking around in. It owns a few bottles and has opinions about them, so feel free to edit both.', 'Leeds', 'learning', false, 'admin', '#8E7F6A', true, now() - interval '2880 hours'),
  ('29e2df9c-7597-50a4-818f-264cf619ed2d', 'vetiverandrain', 'Priya S.', 'Monsoon person. If it smells like wet stone, crushed leaves or an umbrella drying in the hallway, I want to try it.', 'Bengaluru', 'enthusiast', false, 'member', '#6F7F78', true, now() - interval '5208 hours'),
  ('c7590625-3183-58ed-b667-1f8803bce65a', 'm.okonkwo', 'Chidi O.', 'Architect. I collect ambers, leathers and anything with smoke in it, and I keep a spreadsheet my wife pretends not to know about.', 'Lagos', 'collector', false, 'member', '#8A6E6A', true, now() - interval '7536 hours'),
  ('b7d6a76a-5980-5d53-abe0-ac64e1213b75', 'hollis_k', 'Hollis K.', 'Fragrance evaluator by day, which mostly means smelling forty versions of the same shampoo. Off the clock I wear the strange stuff.', 'Rotterdam', 'professional', false, 'member', '#7A7590', true, now() - interval '9864 hours'),
  ('6a68dcde-1521-55b7-b432-c639bbe35e1d', 'nightshiftnora', 'Nora', 'Night-shift nurse. I wear one spray of something quiet at work and save anything louder for my days off.', 'Glasgow', 'learning', false, 'member', '#7E8A62', true, now() - interval '12192 hours'),
  ('7075a2fa-eadc-5f98-a644-87c296fc4db7', 'tobi.sprays', 'Tobi A.', 'Second-year engineering student. Got into this because a guy in my lab always smelled good and would not tell me what it was.', 'Toronto', 'new', false, 'member', '#9A7B52', true, now() - interval '14520 hours'),
  ('3c0c544b-a6a4-524c-93bf-6f8c3a9eff6e', 'lena.wirth', 'Lena W.', 'Forty years of chypres, aldehydes and the occasional mistake. I keep my vintage bottles in a wine fridge and I am not sorry.', 'Vienna', 'collector', false, 'member', '#5F6F7F', true, now() - interval '16848 hours'),
  ('ce02c6b5-4f18-5b8b-b1bd-524eac8d7525', 'sunil_dxb', 'Sunil R.', 'Logistics manager. Big ambers in winter, something blue for the office, and I will always tell you what I paid.', 'Dubai', 'enthusiast', false, 'member', '#8E7F6A', true, now() - interval '19176 hours'),
  ('537b5f39-c85c-5283-b071-55cd08018bb8', 'cozykat', 'Kat', 'Bakery smells forever. I started with body mists and I am slowly working my way up to things that last past lunch.', 'Austin', 'learning', false, 'member', '#6F7F78', true, now() - interval '21504 hours'),
  ('7f420c66-ff31-5715-a784-b92ea57fbf6a', 'yuki.tsuno', 'Yuki T.', 'Tea shop on weekdays, temple walks on weekends. I like scents that sit close and do not ask for attention.', 'Osaka', 'enthusiast', false, 'member', '#8A6E6A', true, now() - interval '23832 hours'),
  ('38de4a7a-d400-5628-9654-7846f8180fc7', 'fernhollow', 'Wren', 'Trail crew in summer, woodworking in winter. Most of what I wear smells like one of those two jobs.', 'Vancouver', 'enthusiast', false, 'member', '#7A7590', true, now() - interval '26160 hours'),
  ('7f152c34-21e6-5d77-962a-1c0bd1c11a02', 'gabriel.mtz', 'Gabriel M.', 'It is summer here most of the year, so I hunt for fresh scents that are not the same blue bottle everyone in my office wears.', 'Mexico City', 'enthusiast', false, 'member', '#7E8A62', true, now() - interval '28488 hours'),
  ('c486a412-1fa7-5c2c-81f2-c8c04c859c6c', 'aunt_bea', 'Bea', 'Retired librarian. My daughter gave me a sample set for my seventieth and now there is a shelf where the cookbooks used to be.', 'Melbourne', 'learning', false, 'member', '#9A7B52', true, now() - interval '30816 hours'),
  ('94aabbb7-d45c-57b5-814f-2b5eb76ffdfd', 'quietpip', 'Pip', 'Mostly here to work out what my partner wears. No bottles of my own yet.', 'Wellington', 'new', false, 'member', '#5F6F7F', true, now() - interval '33144 hours'),
  ('6a460d90-51ff-5ec0-b518-1c6bd880e5ba', 'jonas.e', 'Jonas E.', 'Cyclist and cologne loyalist. I splash, I do not spray, and I reapply at lunch without shame.', 'Hamburg', 'enthusiast', false, 'member', '#8E7F6A', true, now() - interval '4272 hours'),
  ('2d380fda-0fd2-55e4-b115-8d0d10f9652a', 'delphine.r', 'Delphine R.', 'Eleven years on a department store fragrance counter. I have sprayed a thousand blotters and I still get excited about a good musk.', 'Lyon', 'professional', false, 'member', '#6F7F78', true, now() - interval '6600 hours'),
  ('dc28a2e1-751e-52a7-a846-94a375a52c93', 'thebluebottleguy', 'Marcus', 'Sales rep, lots of handshakes. I chase compliments and I am honest about it.', 'Atlanta', 'enthusiast', false, 'member', '#8A6E6A', true, now() - interval '8928 hours'),
  ('ccc543f5-2842-5547-903c-05527d812f94', 'ana.lucia', 'Ana L.', 'Dentist, mother of two, lover of white flowers. English is my second language so be kind with my reviews.', 'São Paulo', 'learning', false, 'member', '#7A7590', true, now() - interval '11256 hours'),
  ('49ad30df-9ca6-5e99-b9d2-828cdc511721', 'sofie.lund', 'Sofie L.', 'Graphic designer with a small flat and a big shelf. Mostly pale, cold, quiet things. I own one sweet perfume and I am working on it.', 'Copenhagen', 'collector', false, 'member', '#7E8A62', true, now() - interval '13584 hours'),
  ('840ca586-3cf9-5cbc-a4b6-75a44dfb9269', 'oudhound', 'Faisal A.', 'Grew up with my grandfather burning resin on Fridays. I compare everything to that smell and most things lose.', 'Riyadh', 'collector', false, 'member', '#9A7B52', true, now() - interval '15912 hours'),
  ('1cbfadf5-479c-5ac2-9948-91009ed2a79f', 'budgetbasil', 'Basil', 'Teacher on a teacher salary. I test the expensive ones so you know whether the cheap one is close enough.', 'Manchester', 'enthusiast', false, 'member', '#5F6F7F', true, now() - interval '18240 hours'),
  ('56fc89c8-504f-5a98-b1e0-cd8bed1bcf84', 'mei.lin', 'Mei L.', 'Accountant. It is 32 degrees and humid here every day, so I mostly want to smell like a clean towel.', 'Singapore', 'new', false, 'member', '#8E7F6A', true, now() - interval '20568 hours'),
  ('307c9d70-bf43-5958-95b3-e997cae55064', 'inkblot.ivy', 'Ivy', 'Printmaker. I like perfumes that smell like a workshop: ink, solvent, hot metal, burnt wood. Vanilla people, I respect you from a distance.', 'Edinburgh', 'enthusiast', false, 'member', '#6F7F78', true, now() - interval '22896 hours'),
  ('81463333-3ee7-5601-8bdd-8225aa8918d9', 'coachdre', 'Dre', 'High school PE teacher and assistant basketball coach. Three bottles, all of them blue.', 'Chicago', 'learning', true, 'member', '#8A6E6A', true, now() - interval '25224 hours');
