insert into public.lists (id, user_id, slug, title, description, is_public, is_demo, created_at) values
  ('9d5ad694-f9b7-54e7-8bf8-613b760b7a36', '537b5f39-c85c-5283-b071-55cd08018bb8', 'vanilla-without-tobacco', 'Vanilla without the tobacco', 'For people who love vanilla but find tobacco notes too heavy. Sweet, creamy and boozy directions, no smoke.', true, true, now() - interval '240 hours'),
  ('4240f5d3-8a26-52c0-9c7a-bda83bf67d6e', '7f152c34-21e6-5d77-962a-1c0bd1c11a02', 'fresh-but-not-blue', 'Fresh, but not the usual blue bottle', 'Summer-friendly fragrances that sit outside the ambroxan-and-pepper crowd.', true, true, now() - interval '1128 hours'),
  ('ce2db84b-206b-53b6-95d9-9c54113e2229', '2d380fda-0fd2-55e4-b115-8d0d10f9652a', 'first-five-bottles', 'Five very different first bottles', 'A starter spread across the main families, so you learn what you like before you buy deeper.', true, true, now() - interval '2016 hours'),
  ('c7a3b77e-e3b7-559e-9480-10c045a53dd6', '29e2df9c-7597-50a4-818f-264cf619ed2d', 'rainy-day-shelf', 'Rainy day shelf', 'Iris, vetiver, incense and woods for grey weather.', true, true, now() - interval '2904 hours'),
  ('050d5f67-35c2-5cee-824c-95f99d5a0d24', '1cbfadf5-479c-5ac2-9948-91009ed2a79f', 'under-50-dollars', 'Under $50 at typical retail', 'Prices move a lot; these are usually found under fifty dollars for a full bottle.', true, true, now() - interval '3792 hours');
insert into public.list_items (list_id, fragrance_id, position, note) values
  ('9d5ad694-f9b7-54e7-8bf8-613b760b7a36', 'b2b219a2-d22b-51e9-b818-1f1e13af6600', 0, 'Vanilla with citrus and a powdery, resinous base. The classic reference.'),
  ('9d5ad694-f9b7-54e7-8bf8-613b760b7a36', '916b23d2-5590-528e-820b-895c1ab89b43', 1, 'Marshmallow-soft orange blossom and vanilla.'),
  ('9d5ad694-f9b7-54e7-8bf8-613b760b7a36', '33125977-2cbc-5d2c-9c22-68baf45d2f1c', 2, 'Praline and iris; a very sweet modern take.'),
  ('9d5ad694-f9b7-54e7-8bf8-613b760b7a36', '37017216-e3c9-5a14-a11b-2b05c2452785', 3, 'Coffee and vanilla over white florals.'),
  ('9d5ad694-f9b7-54e7-8bf8-613b760b7a36', '90d110b3-9c57-5999-ae1b-d3920b55b066', 4, 'Pistachio-salted caramel in a body mist. Short-lived, cheap to try.'),
  ('4240f5d3-8a26-52c0-9c7a-bda83bf67d6e', '0c3dbc70-6685-587b-b4df-8a4f9f9137a3', 0, 'Green mango, lotus and reeds.'),
  ('4240f5d3-8a26-52c0-9c7a-bda83bf67d6e', '7f9268d8-5974-5c4e-a155-51b9c20319e5', 1, 'Salty, mineral, light.'),
  ('4240f5d3-8a26-52c0-9c7a-bda83bf67d6e', '01b40e32-366e-50a8-acd4-441037fb29dc', 2, 'Fig leaf and fig wood.'),
  ('4240f5d3-8a26-52c0-9c7a-bda83bf67d6e', 'f214494e-dc23-5b67-a10a-091b0e621b83', 3, 'A 1960s citrus-aromatic cologne structure.'),
  ('4240f5d3-8a26-52c0-9c7a-bda83bf67d6e', '6437bd31-44df-5108-b822-78d19ae45db0', 4, 'Iris and neroli, soapy and clean.'),
  ('ce2db84b-206b-53b6-95d9-9c54113e2229', '65c20ca3-3513-5ba0-a424-72ba1b845a51', 0, 'Woody, mineral, orange.'),
  ('ce2db84b-206b-53b6-95d9-9c54113e2229', '57d337ab-3d68-59a5-b5b6-c9c6a939a0f3', 1, 'Modern chypre: citrus, rose, patchouli.'),
  ('ce2db84b-206b-53b6-95d9-9c54113e2229', '1f15d7e9-9ec3-5858-9262-fd6ee4d5d2d0', 2, 'Sandalwood, leather and violet; a niche landmark.'),
  ('ce2db84b-206b-53b6-95d9-9c54113e2229', '9be8a2f0-d295-5aeb-971c-6f99cc5e0de6', 3, 'Dense, sweet, spiced.'),
  ('ce2db84b-206b-53b6-95d9-9c54113e2229', '353750cb-d63c-55a7-82c4-f9400136b2da', 4, 'One woody-ambery molecule. A lesson in what a single material does.'),
  ('c7a3b77e-e3b7-559e-9480-10c045a53dd6', '2e3cfee1-9758-54a2-9653-6147449d92bd', 0, 'Clean vetiver with citrus.'),
  ('c7a3b77e-e3b7-559e-9480-10c045a53dd6', 'f1e82d0e-2aaf-5847-8304-5af917ca9540', 1, 'Iris over cacao and woods.'),
  ('c7a3b77e-e3b7-559e-9480-10c045a53dd6', '38b37b9f-c77a-5a0d-8eb8-7a680d032983', 2, 'Pine, juniper and vanilla.'),
  ('c7a3b77e-e3b7-559e-9480-10c045a53dd6', '19cf2561-587d-5c34-bec6-8851996fa008', 3, 'Rum, tobacco leaf, vanilla.'),
